Object.assign(ACTS.run,{l16:X('ฝึกวิ่งและมวยปล้ำที่โรงยิมนาเซียม','Train at running and wrestling in the gymnasium'),c16:X('วิ่งแข่งกับเด็กอื่นเปลือยเท้า','Race the other children barefoot')});
Object.assign(ACTS.build,{l16:X('ก่อกำแพงหินกั้นขั้นบันไดบนเนินเขา','Build stone terrace walls on the hillside')});
Object.assign(ACTS.trade,{l16:X('ซื้อขายที่อะกอรา ลานตลาดกลางเมือง','Buy and sell in the agora, the town square')});
Object.assign(ACTS.story,{l16:X('ฟังนักขับลำนำท่องเรื่องสงครามกรุงทรอย','Listen to a bard recite the war at Troy'),c16:X('ฟังยายเล่านิทานเทพเจ้าบนเขาโอลิมปัส','Listen to grandmother tell of the gods on Olympus')});
Object.assign(ACTS.stars,{l16:X('ดูดาวและถกเถียงว่าโลกกลมหรือแบน','Watch the stars and argue whether the Earth is round')});
Object.assign(ACTS.child,{l16:X('ดูแลเด็กและคนป่วยในบ้าน','Care for the children and the sick at home')});
