const GUMP16=[
G16({id:'g16_sappho',a:[6,45],cond:S=>S.rg==='les'&&S.ya<=2640&&S.ya>=2595,t:X('เพลงของซัปโฟ','Sappho’s songs'),
 x:X('ที่บ้านหลังหนึ่งในมิทิลีนี ผู้หญิงชื่อซัปโฟสอนเด็กสาวร้องเพลงและเล่นพิณ เธอร้องเพลงเกี่ยวกับความรักและความคิดถึง แทนที่จะเป็นเพลงเรื่องสงครามแบบที่ผู้ชายร้องกัน','In a house in Mytilene a woman named Sappho teaches girls to sing and play the lyre. She sings of love and longing instead of the war songs the men sing.'),
 n:X('ซัปโฟมีชีวิตราว 630–570 ปีก่อนคริสตกาล ชาวกรีกยุคหลังนับเธอเป็น “แรงบันดาลใจองค์ที่สิบ” บทกวีเก้าเล่มของเธอหายไปเกือบหมด เหลือบทที่สมบูรณ์เพียงบทเดียว บางส่วนพบบนเศษกระดาษปาปิรุสที่ใช้ห่อมัมมี่ และในปี 2014 มีการพบบทกวีบทใหม่ของเธอ','Sappho lived about 630–570 BCE. Later Greeks counted her as “the tenth Muse”. Her nine books of poems are almost all lost: only one poem survives complete. Some pieces were found on papyrus used to wrap mummies, and a new poem of hers was identified in 2014.'),
 o:[opt(X('ขอเรียนร้องเพลงด้วย','Ask to learn to sing'),S=>{meet16(S,'sappho');fx({so:3,b:4});return X('เสียงคุณสั่นตอนร้องครั้งแรก ซัปโฟยิ้มแล้วบอกว่า “ความรักก็ทำให้เสียงสั่นแบบนั้นแหละ”','Your voice trembles the first time. Sappho smiles and says love makes voices tremble like that.')}),
    opt(X('แอบฟังอยู่หน้าประตู','Listen at the door'),S=>{meet16(S,'sappho');fx({kn:2,b:2});return X('คุณจำได้แค่ท่อนเดียว แต่ร้องมันไปจนแก่','You remember only one line, but you sing it until you are old.')})]}),
G16({id:'g16_solon',a:[14,80],cond:S=>S.rg==='ath'&&yr16(2620,2616)(S),t:X('ปลดภาระ','The shaking-off of burdens'),
 x:X('ที่ลานกลางเมือง ชายชื่อโซลอนประกาศกฎหมายใหม่: หนี้ที่เอาตัวคนค้ำประกันถูกยกเลิกทั้งหมด หลักหินที่ปักบอกว่าที่ดินติดหนี้ถูกถอนทิ้ง และชาวเอเธนส์ที่ถูกขายเป็นทาสเพราะหนี้จะถูกไถ่ตัวกลับมา','In the square a man named Solon announces new laws: every debt secured on a person is cancelled, the stone markers that showed land was pledged are pulled up, and Athenians sold as slaves for debt will be bought back.'),
 n:X('ในปี 594 ปีก่อนคริสตกาล โซลอนได้รับเลือกให้แก้วิกฤตหนี้ที่เกือบทำให้เอเธนส์เกิดสงครามกลางเมือง การปฏิรูปนี้เรียกว่า “ไซซัคเธีย” แปลว่า การสลัดภาระ หลังจากนั้นห้ามเอาตัวพลเมืองเอเธนส์ค้ำหนี้อีก โซลอนเขียนบทกวีอวดว่าเขาปลดปล่อยแผ่นดินที่เคยเป็นทาส','In 594 BCE Solon was chosen to settle a debt crisis that had brought Athens close to civil war. His reform was called the seisachtheia, “the shaking-off of burdens”. From then on no Athenian could be pledged as security for a debt. Solon wrote poems boasting that he had freed the enslaved earth.'),
 o:[opt(X('โห่ร้องดีใจ','Cheer'),S=>{meet16(S,'solon');if(S.debt){S.debt=0;S.debtY=0}if(S.cls==='slave'&&S.rg==='ath'){S.cls='free';ms(X('เป็นอิสระด้วยกฎหมายของโซลอน','Freed by Solon’s law'))}fx({b:6});return X('คนจนร้องไห้ คนรวยบ่นว่าเสียเงิน โซลอนบอกว่าถ้าทั้งสองฝ่ายไม่พอใจ แปลว่าเขาทำถูกแล้ว','The poor weep for joy, the rich complain of their losses. Solon says that if both sides are unhappy, he must have got it right.')}),
    opt(X('ถามว่ากฎหมายจะอยู่ได้นานแค่ไหน','Ask how long the laws will last'),S=>{meet16(S,'solon');if(S.debt){S.debt=0;S.debtY=0}fx({kn:3});return X('โซลอนตอบว่าเขาจะออกเดินทางไปต่างแดนสิบปี เพื่อไม่ให้ใครมาขอให้เขาแก้กฎหมาย','Solon says he will go abroad for ten years, so no one can pester him to change the laws.')})]}),
G16({id:'g16_thales',a:[5,85],cond:S=>['mil','les'].includes(S.rg)&&yr16(2611,2609)(S),t:X('ดวงอาทิตย์หายไป','The sun goes out'),
 x:X('ตอนบ่าย ฟ้ามืดลงจนเห็นดาว นกหยุดร้อง ทุกคนกรีดร้อง ยกเว้นชายแก่ชื่อทาลีส ที่ยืนยิ้มเหมือนรอวันนี้อยู่แล้ว','In the afternoon the sky goes dark enough to see stars. The birds fall silent and everyone screams, except an old man named Thales, who stands smiling as if he had been waiting for this.'),
 n:X('เฮโรโดตัสเล่าว่าทาลีสแห่งมิเลทัสทำนายสุริยุปราคาครั้งนี้ไว้ล่วงหน้า ✦ และกองทัพลิเดียกับมีเดียที่กำลังรบกันตกใจจนยอมสงบศึก นักดาราศาสตร์คำนวณว่าเป็นสุริยุปราคาวันที่ 28 พฤษภาคม 585 ปีก่อนคริสตกาล นักวิชาการยังสงสัยว่าทาลีสทำนายได้จริงแค่ไหน แต่เขาคือคนแรกๆ ที่พยายามอธิบายโลกด้วยเหตุผลแทนเทพเจ้า','Herodotus says Thales of Miletus foretold this eclipse ✦, and that the Lydian and Median armies fighting that day were so frightened they made peace. Astronomers date it to 28 May 585 BCE. Scholars doubt how far Thales could really predict it, but he was among the first to explain the world by reasoning rather than gods.'),
 o:[opt(X('วิ่งไปถามทาลีส','Run and ask Thales'),S=>{meet16(S,'thales');fx({kn:4});return X('ทาลีสบอกว่าดวงจันทร์เดินมาบังดวงอาทิตย์ ไม่มีเทพองค์ไหนโกรธใคร คุณไม่ค่อยเชื่อ แต่ก็ไม่กลัวอีก','Thales says the Moon has passed in front of the Sun and no god is angry with anyone. You are not sure you believe it, but you are no longer afraid.')}),
    opt(X('ซ่อนตัวใต้โต๊ะ','Hide under the table'),S=>{meet16(S,'thales');fx({b:-1});return X('พอแสงกลับมา คุณได้ยินทาลีสหัวเราะอยู่ข้างนอก','When the light comes back, you hear Thales laughing outside.')})]}),
G16({id:'g16_croesus',a:[12,80],cond:S=>['mil','les'].includes(S.rg)&&yr16(2576,2571)(S),t:X('คำทำนายของเดลฟี','The oracle of Delphi'),
 x:X('ทูตของกษัตริย์ครีซัสแห่งลิเดียผู้ร่ำรวยที่สุดในโลก ขึ้นเรือมาพร้อมของถวายทองคำไปถามเทพที่เดลฟีว่าควรทำสงครามกับเปอร์เซียหรือไม่ เขาจ้างคนช่วยขนของ','The envoys of King Croesus of Lydia, the richest man in the world, take ship with gold offerings for Delphi, to ask the god whether to make war on Persia. They hire people to help carry.'),
 n:X('เฮโรโดตัสเล่าว่าเทพที่เดลฟีตอบว่า ถ้าครีซัสทำสงครามกับเปอร์เซีย เขาจะทำลายจักรวรรดิใหญ่ ✦ ครีซัสบุก และจักรวรรดิที่ถูกทำลายคือของตัวเอง ราว 547 ปีก่อนคริสตกาล หลังจากนั้นเมืองกรีกในไอโอเนียก็ตกอยู่ใต้เปอร์เซีย','Herodotus says the god at Delphi answered that if Croesus made war on Persia he would destroy a great empire ✦. Croesus attacked, and the empire destroyed, around 547 BCE, was his own. After that the Greek cities of Ionia came under Persia.'),
 o:[opt(X('ช่วยขนทองไปเดลฟี','Help carry the gold to Delphi'),S=>{meet16(S,'croesus');S.ag+=2;fx({tr:3,kn:2});S.saw.delphi=1;return X('คุณได้ยินคำทำนายกับหูตัวเอง ทูตยิ้มกว้าง แต่คุณสงสัยว่าจักรวรรดิไหนกันแน่','You hear the oracle with your own ears. The envoys beam, but you wonder which empire it means.')}),
    opt(X('ไม่ไป ข่าวลือว่าเปอร์เซียน่ากลัว','Stay: rumour says Persia is terrible'),S=>{meet16(S,'croesus');fx({b:1});return X('สองปีต่อมา ทัพเปอร์เซียมาถึงชายฝั่งของคุณ','Two years later the Persian army reaches your coast.')})]}),
G16({id:'g16_milo',a:[7,80],cond:yr16(2565,2541),t:X('เทศกาลที่โอลิมเปีย','The festival at Olympia'),
 x:X('ทุกสี่ปี ทุกเมืองกรีกประกาศพักรบ ให้ผู้คนเดินทางไปโอลิมเปียได้อย่างปลอดภัย คุณไปกับครอบครัว และเห็นนักมวยปล้ำร่างยักษ์จากโครตอนชื่อไมโล ที่ไม่มีใครล้มได้','Every four years the Greek cities declare a truce so people can travel safely to Olympia. You go with your family and see a giant wrestler from Croton named Milo, whom no one can throw.'),
 n:X('ไมโลชนะมวยปล้ำที่โอลิมเปียหกครั้ง ครั้งแรกในรุ่นเด็ก ราว 540–516 ปีก่อนคริสตกาล ตำนานเล่าว่าเขาแบกลูกวัวทุกวันจนมันโตเป็นวัว แรงของเขาจึงเพิ่มขึ้นทุกวันเหมือนกัน ✦ นักกีฬาโอลิมปิกแข่งแบบเปลือย และผู้หญิงที่แต่งงานแล้วห้ามเข้าชม','Milo won the wrestling at Olympia six times, the first as a boy, between about 540 and 516 BCE. Legend says he carried a calf every day until it was a bull, so his strength grew day by day too ✦. Olympic athletes competed naked, and married women were barred from watching.'),
 o:[opt(X('แทรกตัวไปดูข้างหน้า','Squeeze to the front'),S=>{meet16(S,'milo');fx({sv:2,b:4});return X('ไมโลเดินผ่านคุณไปใกล้จนได้กลิ่นน้ำมันมะกอกที่ทาตัว ไหล่ของเขากว้างเท่าประตูบ้าน','Milo walks past close enough that you smell the olive oil on his skin. His shoulders are as wide as a door.')}),
    opt(X('กลับบ้านไปแบกลูกแพะทุกวัน','Go home and carry a kid goat every day'),S=>{meet16(S,'milo');fx({sv:4,h:2});return X('สามเดือนต่อมา แพะหนักเกินกว่าคุณจะยกไหว คุณสรุปว่าตำนานนี้ต้องมีอะไรผิดสักอย่าง','Three months later the goat is too heavy to lift, and you conclude something must be wrong with the legend.')})]}),
G16({id:'g16_pyth',a:[10,80],cond:S=>(S.rg==='syr'&&yr16(2555,2520)(S))||(S.rg==='mil'&&yr16(2575,2556)(S)),t:X('ชายที่ไม่กินถั่ว','The man who will not eat beans'),
 x:X('ชายชื่อพีทาโกรัสสอนว่าทุกสิ่งในโลกคือตัวเลข เขาดีดสายพิณให้ดู สายที่ยาวครึ่งหนึ่งให้เสียงสูงขึ้นหนึ่งช่วงคู่แปดพอดี ลูกศิษย์ของเขาห้ามกินถั่วปากอ้า และไม่มีใครรู้ว่าทำไม','A man named Pythagoras teaches that everything in the world is number. He plucks a lyre string: a string half as long sounds exactly an octave higher. His followers may not eat broad beans, and nobody knows why.'),
 n:X('พีทาโกรัสเกิดที่เกาะซามอสใกล้มิเลทัส และย้ายไปตั้งสำนักที่เมืองโครตอนทางใต้ของอิตาลีราว 530 ปีก่อนคริสตกาล เขาไม่ได้เขียนอะไรไว้เลย เรื่องข้อห้ามกินถั่วและการค้นพบอัตราส่วนของเสียงดนตรีมาจากคนรุ่นหลัง ✦ และทฤษฎีบทที่ใช้ชื่อเขา ชาวบาบิโลนรู้จักมาก่อนแล้วกว่าพันปี','Pythagoras was born on Samos, near Miletus, and founded a school at Croton in southern Italy around 530 BCE. He wrote nothing himself: the bean rule and the discovery of musical ratios come from later writers ✦. The theorem named after him was known to the Babylonians more than a thousand years earlier.'),
 o:[opt(X('ลองวัดสายพิณเอง','Measure the strings yourself'),S=>{meet16(S,'pyth');fx({kn:4,cr:1});return X('สายสองในสามให้เสียงห้า สายสามในสี่ให้เสียงสี่ คุณนอนไม่หลับทั้งคืนเพราะตื่นเต้น','Two-thirds of a string sounds a fifth, three-quarters a fourth. You lie awake all night with excitement.')}),
    opt(X('กินถั่วต่อหน้าเขา','Eat beans in front of him'),S=>{meet16(S,'pyth');fx({b:2,p:-1});return X('ลูกศิษย์ของเขามองคุณเหมือนคุณกินเนื้อพ่อแม่ตัวเอง','His followers look at you as if you had eaten your own parents.')})]}),
G16({id:'g16_marathon',a:[18,60],cond:S=>S.rg==='ath'&&S.sex==='m'&&S.cls!=='slave'&&yr16(2516,2514)(S),t:X('ที่ราบมาราธอน','The plain of Marathon'),
 x:X('กองทัพเปอร์เซียขึ้นฝั่งที่อ่าวมาราธอน ห่างจากเอเธนส์ราวสี่สิบกิโลเมตร ชาวเอเธนส์ทุกคนที่มีโล่และหอกต้องเดินทัพไป มีแค่ชาวพลาเทียไม่กี่ร้อยคนมาช่วย','The Persian army has landed in the bay of Marathon, about forty kilometres from Athens. Every Athenian with a shield and spear must march, with only a few hundred Plataeans to help.'),
 n:X('ในปี 490 ปีก่อนคริสตกาล ชาวเอเธนส์ชนะที่มาราธอน เฮโรโดตัสบอกว่าชาวเอเธนส์ตาย 192 คน ชาวเปอร์เซียราว 6,400 คน ก่อนการรบ นักวิ่งชื่อเฟดิปปิดีสวิ่งไปขอความช่วยเหลือจากสปาร์ตาราว 240 กิโลเมตรภายในสองวัน เรื่องคนวิ่งจากมาราธอนไปบอกข่าวชนะที่เอเธนส์แล้วล้มตาย เป็นเรื่องที่เล่ากันหลายร้อยปีต่อมา ✦ และเป็นที่มาของการวิ่งมาราธอน','In 490 BCE the Athenians won at Marathon. Herodotus says 192 Athenians died and about 6,400 Persians. Before the battle a runner named Pheidippides ran about 240 kilometres to Sparta for help in two days. The story of a runner who carried news of victory from Marathon to Athens and then dropped dead is told only centuries later ✦, and gave the marathon race its name.'),
 o:[opt(X('วิ่งเข้าใส่แถวเปอร์เซีย','Charge the Persian line'),S=>{meet16(S,'marathon');if(rnd()<.12){fx({h:-18});S.inj=1;return X('ลูกธนูปักต้นขาคุณ แต่คุณยังวิ่งต่อจนถึงเรือของศัตรู','An arrow strikes your thigh, but you keep running all the way to the enemy ships.')}fx({sv:4,p:8,b:5});ms(X('รบที่มาราธอน','Fought at Marathon'));return X('ชาวเปอร์เซียหนีลงเรือ ทั้งชีวิตหลังจากนั้น คุณไม่เคยเบื่อที่จะเล่าเรื่องวันนี้','The Persians flee to their ships. For the rest of your life you never tire of telling about this day.')}),
    opt(X('อยู่แถวหลัง ระวังตัว','Keep to the back ranks'),S=>{meet16(S,'marathon');fx({p:3});ms(X('อยู่ในกองทัพที่มาราธอน','Was in the army at Marathon'));return X('คุณไม่ได้แทงใครเลย แต่ทุกคนที่ไปมาราธอนก็ได้ชื่อว่าเป็นวีรบุรุษ','You never stab anyone, but everyone who was at Marathon is called a hero.')})]}),
G16({id:'g16_aristides',a:[18,80],cond:S=>S.rg==='ath'&&S.sex==='m'&&S.cls!=='slave'&&S.cls!=='dep'&&yr16(2508,2506)(S),t:X('เปลือกหม้อ','The potsherd'),
 xf:S=>S.lit>=20?X('วันออกเสียงเนรเทศ ชาวนาคนหนึ่งที่อ่านไม่ออกยื่นเศษหม้อให้คุณ ขอให้เขียนชื่อ “อริสทิดีส” ลงไป คุณถามว่าอริสทิดีสทำอะไรให้เขา เขาตอบว่า “ไม่ได้ทำอะไร ข้าแค่เบื่อที่ได้ยินทุกคนเรียกเขาว่า คนยุติธรรม”','On the day of the exile vote, a farmer who cannot read hands you a potsherd and asks you to write “Aristides” on it. You ask what Aristides ever did to him. “Nothing,” he says. “I’m just sick of hearing everyone call him the Just.”'):X('วันออกเสียงเนรเทศ คุณอ่านเขียนไม่เป็น จึงยื่นเศษหม้อให้ชายข้างๆ ช่วยเขียนชื่อ “อริสทิดีส” ชายคนนั้นถามว่าอริสทิดีสทำอะไรให้คุณ','On the day of the exile vote you cannot write, so you hand your potsherd to the man beside you and ask him to write “Aristides”. He asks what Aristides ever did to you.'),
 n:X('ชาวเอเธนส์ใช้การ “ออสตราซิซึม” เนรเทศนักการเมืองที่ดูมีอำนาจเกินไปออกจากเมืองสิบปี โดยเขียนชื่อบนเศษหม้อดินเผา ต้องมีผู้ลงคะแนนอย่างน้อยราว 6,000 คน พลูทาร์กเล่าว่าชายที่ขอให้เขียนชื่ออริสทิดีสคือตัวอริสทิดีสเอง และเขาก็เขียนให้ ✦ อริสทิดีสถูกเนรเทศในปี 482 ปีก่อนคริสตกาล และถูกเรียกกลับมาก่อนการรบที่ซาลามิส นักโบราณคดีพบเศษหม้อแบบนี้หลายพันชิ้น บางชิ้นเขียนด้วยลายมือเดียวกัน','Athenians used ostracism to send a politician who seemed too powerful out of the city for ten years, writing his name on a broken piece of pottery. At least about 6,000 votes were needed. Plutarch says the man asked to write Aristides’ name was Aristides himself, and that he wrote it ✦. Aristides was ostracised in 482 BCE and recalled before the battle of Salamis. Archaeologists have found thousands of these sherds, some written in the same handwriting.'),
 o:[opt(X('เขียนชื่อตามที่ขอ','Write the name as asked'),S=>{meet16(S,'aristides');fx({so:2,kn:2});return X('คุณเพิ่งรู้ทีหลังว่าชายถือเศษหม้ออีกคนที่ยืนดูอยู่ใกล้ๆ คืออริสทิดีสเอง','Only later do you learn that the man standing nearby watching was Aristides himself.')}),
    opt(X('เขียนชื่อคนอื่นแทน','Write a different name'),S=>{meet16(S,'aristides');fx({b:2,p:1});return X('ชื่อนั้นได้แค่เสียงเดียว คือเสียงของคุณ','That name gets one vote: yours.')})]}),
G16({id:'g16_salamis',a:[14,60],cond:S=>['ath','cor'].includes(S.rg)&&S.sex==='m'&&yr16(2506,2504)(S),t:X('ช่องแคบซาลามิส','The straits of Salamis'),
 x:X('ธีมิสโทคลีสสั่งให้ทุกคนลงเรือรบ เรือไตรรีมแต่ละลำต้องการฝีพายราว 170 คน คนจนที่ไม่มีเงินซื้อโล่ก็มีค่าเท่ากับขุนนางเมื่อจับไม้พาย ในช่องแคบแคบๆ เรือเปอร์เซียที่มากกว่ากลับชนกันเอง','Themistocles orders everyone onto the warships. Each trireme needs about 170 rowers, and a poor man who cannot afford a shield is worth as much as a noble once he holds an oar. In the narrow strait the larger Persian fleet crowds and crashes into itself.'),
 n:X('ในปี 480 ปีก่อนคริสตกาล กองเรือกรีกชนะเปอร์เซียที่ซาลามิส เรือไตรรีมมีฝีพายสามชั้นและหัวเรือหุ้มสัมฤทธิ์ไว้พุ่งชน หลังจากนั้นคนจนที่เป็นฝีพายได้เสียงในการเมืองเอเธนส์มากขึ้น นักประวัติศาสตร์หลายคนเชื่อว่าประชาธิปไตยของเอเธนส์เติบโตเพราะกองเรือ','In 480 BCE the Greek fleet defeated Persia at Salamis. A trireme had three banks of rowers and a bronze ram on its prow. Afterwards the poor men who rowed gained more say in Athenian politics: many historians think Athenian democracy grew with its navy.'),
 o:[opt(X('พายจนมือแตก','Row until your hands split'),S=>{meet16(S,'salamis');fx({sv:4,p:6,h:-3});ms(X('พายเรือรบที่ซาลามิส','Rowed at Salamis'));return X('เสียงขลุ่ยให้จังหวะ เสียงไม้พายพร้อมกันเป็นร้อย แล้วเสียงไม้แตกเมื่อหัวเรือชนข้างเรือศัตรู','The piper gives the stroke, a hundred oars strike as one, then wood splinters as the ram meets an enemy hull.')}),
    opt(X('ช่วยขนคนแก่และเด็กข้ามไปเกาะ','Ferry the old and the children to the island'),S=>{meet16(S,'salamis');fx({so:4,b:4});return X('จากบนเกาะ คุณเห็นทะเลเต็มไปด้วยไม้และควัน จนรู้ว่าใครชนะเมื่อเห็นเรือที่หนีไป','From the island you watch the sea fill with wreckage and smoke, and know who has won only when you see whose ships are fleeing.')})]}),
G16({id:'g16_leonidas',a:[6,80],cond:S=>S.rg==='spa'&&yr16(2506,2504)(S),t:X('สามร้อยคน','The three hundred'),
 x:X('กษัตริย์เลโอนิดัสเลือกทหาร 300 คนไปรักษาช่องเขาเทอร์โมพิลีจากทัพเปอร์เซีย เขาเลือกเฉพาะคนที่มีลูกชายแล้ว ที่ประตูบ้าน แม่คนหนึ่งยื่นโล่ให้ลูกแล้วพูดว่า “กลับมาพร้อมมัน หรือนอนกลับมาบนมัน”','King Leonidas picks 300 men to hold the pass of Thermopylae against Persia, choosing only men who already have sons. At a door a mother hands her son his shield and says: “Come back with it, or on it.”'),
 n:X('เฮโรโดตัสเขียนว่าเลโอนิดัสเลือกเฉพาะชายที่มีลูกชาย ทั้ง 300 คนตายในปี 480 ปีก่อนคริสตกาล พร้อมทหารกรีกจากเมืองอื่นอีกหลายพันคนที่มักถูกลืม คำพูดของแม่ชาวสปาร์ตา และคำตอบของเลโอนิดัสเมื่อเปอร์เซียสั่งให้วางอาวุธว่า “มาเอาไปสิ” มาจากหนังสือของพลูทาร์กที่เขียนหลังจากนั้นราวหกร้อยปี ✦','Herodotus writes that Leonidas chose only men with sons. All 300 died in 480 BCE, alongside thousands of other Greeks who are usually forgotten. The Spartan mother’s words, and Leonidas’ answer when the Persians told him to lay down his arms, “Come and take them”, come from Plutarch, writing some six hundred years later ✦.'),
 o:[opt(X('ยืนดูขบวนทหารเดินออกไป','Watch the men march out'),S=>{meet16(S,'leonidas');fx({b:-2,p:2});return X('ไม่มีใครร้องไห้ เพราะชาวสปาร์ตาห้ามร้องไห้ คุณกลั้นไว้จนเจ็บคอ','No one weeps, for Spartans may not. You hold it in until your throat aches.')}),
    opt(X('ถามว่าทำไมต้องเป็นคนที่มีลูกแล้ว','Ask why it must be men with sons'),S=>{meet16(S,'leonidas');fx({kn:3});return X('ผู้เฒ่าตอบสั้นๆ ว่า “เพื่อให้มีคนสืบชื่อ”','An elder answers shortly: “So that someone carries on the name.”')})]}),
G16({id:'g16_persae',a:[8,85],cond:S=>S.rg==='ath'&&yr16(2498,2496)(S),t:X('ละครเรื่องชาวเปอร์เซีย','The play called The Persians'),
 x:X('ที่โรงละครกลางแจ้งใต้อะโครโพลิส คนนับหมื่นนั่งบนเนินดูละครของเอสคิลัส เรื่องการพ่ายแพ้ที่ซาลามิส แต่เล่าจากฝั่งชาวเปอร์เซียที่ร้องไห้ คนที่ออกเงินจ้างนักร้องคือหนุ่มชื่อเพริคลีส','In the open-air theatre below the Acropolis, thousands sit on the hillside to watch Aeschylus’ play about Salamis, told from the side of the weeping Persians. The young man who paid for the chorus is called Pericles.'),
 n:X('“ชาวเปอร์เซีย” ของเอสคิลัสแสดงในปี 472 ปีก่อนคริสตกาล เป็นบทละครกรีกที่เก่าที่สุดที่เหลือรอดมาครบ และเป็นละครโศกนาฏกรรมเรื่องเดียวที่เหลือมาซึ่งเล่าเหตุการณ์จริง เอสคิลัสเองเคยรบที่มาราธอน ผู้สนับสนุนการแสดงคือเพริคลีส ซึ่งต่อมาเป็นผู้นำเอเธนส์','Aeschylus’ Persians was staged in 472 BCE. It is the oldest Greek play to survive complete, and the only surviving tragedy about real events. Aeschylus himself had fought at Marathon. Its sponsor was Pericles, later leader of Athens.'),
 o:[opt(X('ร้องไห้ไปกับชาวเปอร์เซีย','Weep with the Persians'),S=>{meet16(S,'persae');fx({b:4,so:2});return X('คุณตกใจที่ตัวเองสงสารศัตรู ทั้งที่พ่อของคุณรบกับพวกเขา','You are startled to pity the enemy, though your father fought them.')}),
    opt(X('โห่เมื่อกษัตริย์เปอร์เซียออกมา','Jeer when the Persian king appears'),S=>{meet16(S,'persae');fx({b:2});return X('ทั้งโรงละครโห่ตามคุณ นักแสดงใต้หน้ากากยืนนิ่ง','The whole theatre jeers along. The actor behind the mask stands still.')})]}),
G16({id:'g16_herodotus',a:[10,80],cond:yr16(2470,2450),t:X('คนเล่าเรื่องที่ถามทุกคน','The storyteller who asks everyone'),
 x:X('ที่โอลิมเปีย ชายจากฮาลิคาร์นัสซัสชื่อเฮโรโดตัสอ่านหนังสือที่เขาเขียนให้ฝูงชนฟัง เรื่องสงครามกับเปอร์เซีย อียิปต์ที่ผู้หญิงไปตลาดและผู้ชายทอผ้า และมดตัวโตเท่าหมาที่ขุดทอง เขาบอกว่าเขาแค่เล่าสิ่งที่คนอื่นเล่าให้ฟัง','At Olympia a man from Halicarnassus named Herodotus reads his book aloud to the crowd: the wars with Persia, Egypt where the women go to market and the men weave, and ants as big as dogs that dig up gold. He says he only reports what others told him.'),
 n:X('เฮโรโดตัสเรียกงานของเขาว่า “ฮิสโตรีอี” แปลว่า การสืบค้น ซึ่งกลายเป็นคำว่า history ในภาษาอังกฤษ เขาจึงถูกเรียกว่า “บิดาแห่งประวัติศาสตร์” และถูกบางคนเรียกว่า “บิดาแห่งการโกหก” เพราะเรื่องอย่างมดขุดทอง เรื่องที่เขาอ่านหนังสือที่โอลิมเปียมาจากนักเขียนรุ่นหลัง ✦','Herodotus called his work historiē, “inquiry”, which became our word history. He is called “the father of history”, and by some “the father of lies” for tales like the gold-digging ants. The story of his reading at Olympia comes from a much later writer ✦.'),
 o:[opt(X('ถามว่าเขาเห็นมดเองไหม','Ask whether he saw the ants himself'),S=>{meet16(S,'herodotus');fx({kn:4});return X('เขาบอกว่าไม่เห็น แต่ชาวเปอร์เซียหลายคนเล่าตรงกัน แล้วเขียนคำถามของคุณลงไปด้วย','He says no, but many Persians told the same story, and he writes down your question too.')}),
    opt(X('เล่าเรื่องบ้านเกิดของคุณให้เขาฟัง','Tell him about your home town'),S=>{meet16(S,'herodotus');fx({so:3,b:2});return X('เขาตั้งใจฟังมาก คุณสงสัยไปตลอดชีวิตว่าเรื่องของคุณอยู่ในหนังสือของเขาหรือเปล่า','He listens intently. All your life you wonder whether your story ended up in his book.')})]}),
G16({id:'g16_pericles',a:[8,85],cond:S=>S.rg==='ath'&&yr16(2457,2455)(S),t:X('คำปราศรัยในพิธีศพ','The funeral speech'),
 x:X('ฤดูหนาวปีแรกของสงคราม ทั้งเมืองมาที่สุสานนอกกำแพงเพื่อฝังทหารที่ตาย เพริคลีสขึ้นยืนบนแท่นสูงและพูดว่า เอเธนส์คือโรงเรียนของกรีกทั้งหมด และคนที่ไม่สนใจเรื่องบ้านเมืองไม่ใช่คนไม่ยุ่ง แต่เป็นคนไร้ประโยชน์','In the first winter of the war the whole city goes to the cemetery outside the walls to bury the dead soldiers. Pericles climbs a high platform and says that Athens is the school of all Greece, and that a man who takes no interest in public affairs is not quiet but useless.'),
 n:X('คำปราศรัยนี้มาจากหนังสือของธิวซิดิดีส ที่บอกตรงๆ ว่าเขาเขียนคำพูดในหนังสือตามที่ “ควรจะพูด” เพราะจำคำต่อคำไม่ได้ จึงเป็นทั้งความคิดของเพริคลีสและของธิวซิดิดีส คำว่าเอเธนส์เป็นประชาธิปไตยเพราะอำนาจอยู่ในมือของคนส่วนใหญ่ มาจากคำปราศรัยนี้ แต่คนส่วนใหญ่ในที่นั้นไม่มีสิทธิ์ออกเสียง','This speech comes from Thucydides, who says plainly that he wrote speeches as they “ought to have been” given, since he could not remember them word for word: so it is both Pericles’ thought and Thucydides’. The line that Athens is a democracy because power lies with the many comes from here, yet most of the people listening could not vote.'),
 o:[opt(X('ฟังจนจบ','Listen to the end'),S=>{meet16(S,'pericles');fx({kn:3,b:3});return X('ผู้หญิงถูกบอกให้เงียบและไม่ให้ใครพูดถึง ทั้งที่พวกเธอคือคนที่ร้องไห้อยู่ข้างหลุมศพ','The women are told to stay quiet and unspoken of, though they are the ones weeping at the graves.')}),
    opt(X('มองหาชื่อของคนที่คุณรู้จักบนแผ่นหิน','Look for a name you know on the stone'),S=>{meet16(S,'pericles');fx({b:-3,so:2});return X('ชื่อเรียงตามเผ่าโดยไม่มีชื่อพ่อหรือยศ ทุกคนเท่ากันเมื่อตาย','The names are listed by tribe, without fathers’ names or rank. Everyone is equal in death.')})]}),
G16({id:'g16_hippo',a:[5,85],cond:S=>['mil','les','ath'].includes(S.rg)&&yr16(2440,2400)(S),t:X('หมอจากเกาะคอส','The doctor from Kos'),
 x:X('หมอเดินทางชื่อฮิปพอคราทีสมาดูญาติของคุณที่ชักล้มลงกับพื้น ทุกคนบอกว่าเทพเจ้าลงโทษ แต่หมอคนนี้ไม่ถวายเครื่องบูชา เขาจับชีพจร ถามว่ากินอะไร ดื่มน้ำจากที่ไหน แล้วจดทุกอย่างลงไป','A travelling doctor named Hippocrates comes to see your relative, who falls to the ground in fits. Everyone says the gods are punishing him, but this doctor makes no offering. He feels the pulse, asks what the man eats and where he drinks, and writes everything down.'),
 n:X('ฮิปพอคราทีส (ราว 460–370 ปีก่อนคริสตกาล) และลูกศิษย์เขียนตำรากว่าหกสิบเล่ม เล่มหนึ่งชื่อ “ว่าด้วยโรคศักดิ์สิทธิ์” บอกว่าโรคลมชักไม่ได้ศักดิ์สิทธิ์มากกว่าโรคอื่น และมีสาเหตุตามธรรมชาติ คำสาบานของฮิปพอคราทีสที่แพทย์ยังพูดถึงทุกวันนี้ อาจเขียนโดยคนรุ่นหลังในสำนักของเขา','Hippocrates (about 460–370 BCE) and his pupils wrote more than sixty medical books. One, On the Sacred Disease, says epilepsy is no more sacred than any other illness and has natural causes. The Hippocratic Oath that doctors still speak of may have been written by later members of his school.'),
 o:[opt(X('ช่วยหมอจดอาการ','Help the doctor take notes'),S=>{meet16(S,'hippo');fx({kn:5});return X('หมอบอกว่า “ชีวิตสั้น ศิลปะยาว” แล้วสอนให้คุณดูสีของปัสสาวะ ซึ่งคุณไม่ได้อยากรู้เลย','The doctor says, “Life is short, the art is long,” then teaches you to study the colour of urine, which you never wanted to know.')}),
    opt(X('แอบถวายไก่ให้เทพเจ้าด้วย เผื่อไว้','Offer a cockerel to the god as well, just in case'),S=>{meet16(S,'hippo');fx({b:2});return X('หมอเห็นแล้วไม่ว่าอะไร แค่บอกว่าให้ญาติคุณกินซุปไก่ตัวนั้นแทน','The doctor sees and says nothing, except that your relative should eat the cockerel as soup instead.')})]}),
G16({id:'g16_socrates',a:[9,75],cond:S=>S.rg==='ath'&&yr16(2470,2426)(S),t:X('ชายที่ถามไม่หยุด','The man who never stops asking'),
 x:X('ในตลาด ชายแก่จมูกบี้เท้าเปล่าชื่อโสกราตีสหยุดคุณไว้แล้วถามว่า “ความกล้าหาญคืออะไร” คุณตอบ เขาถามต่อ คุณตอบอีก จนในที่สุดคุณรู้สึกว่าไม่รู้อะไรเลย คนรอบๆ หัวเราะ','In the market a barefoot old man with a snub nose named Socrates stops you and asks, “What is courage?” You answer; he asks again; you answer again, until at last you feel you know nothing at all. The crowd laughs.'),
 n:X('โสกราตีสไม่เขียนหนังสือเลยสักเล่ม เรารู้จักเขาจากลูกศิษย์ โดยเฉพาะเพลโต วิธีถามต่อไปเรื่อยๆ จนเห็นว่าความเชื่อของเราขัดกันเอง ยังเรียกว่า “วิธีแบบโสกราตีส” จนทุกวันนี้ ในบทสนทนาของเพลโต โสกราตีสบอกว่าเขาฉลาดกว่าคนอื่นแค่ตรงที่ไม่คิดว่าตัวเองรู้ในสิ่งที่ไม่รู้','Socrates wrote no books at all; we know him from his pupils, above all Plato. His way of asking question after question until we see our beliefs contradict each other is still called the Socratic method. In Plato’s dialogues Socrates says he is wiser than others only in not thinking he knows what he does not.'),
 o:[opt(X('ถามเขากลับ','Question him back'),S=>{meet16(S,'socrates');fx({kn:5,so:1});return X('โสกราตีสหัวเราะชอบใจ แล้วถามคำถามที่ยากกว่าเดิม คุณกลับบ้านมาเถียงกับแม่ทั้งคืน','Socrates laughs with delight and asks something even harder. You go home and argue with your mother all night.')}),
    opt(X('เดินหนี','Walk away'),S=>{meet16(S,'socrates');fx({b:1});return X('เขาตะโกนตามหลังว่า “เดินหนีคำถามก็เป็นคำตอบอย่างหนึ่ง” ซึ่งยิ่งน่ารำคาญ','He calls after you that walking away from a question is a kind of answer too, which is even more annoying.')})]}),
G16({id:'g16_trial',a:[30,85],cond:S=>S.rg==='ath'&&S.sex==='m'&&['free','elite'].includes(S.cls)&&yr16(2425,2423)(S),t:X('ลูกขุน 501 คน','Five hundred and one jurors'),
 x:X('คุณถูกจับสลากเป็นลูกขุน วันนี้จำเลยคือโสกราตีส อายุเจ็ดสิบ ข้อหาไม่นับถือเทพของเมืองและทำให้คนหนุ่มเสียคน เขาไม่ขอความเมตตาเลย และบอกว่า “ชีวิตที่ไม่ได้ตรวจสอบ ไม่คุ้มค่าที่มนุษย์จะมีอยู่”','You are chosen by lot as a juror. Today the defendant is Socrates, seventy years old, charged with not honouring the city’s gods and corrupting the young. He begs for no mercy, and says: “The unexamined life is not worth living for a human being.”'),
 n:X('ในปี 399 ปีก่อนคริสตกาล ลูกขุนราว 500 คน ซึ่งต้องเป็นพลเมืองชายอายุ 30 ปีขึ้นไป ตัดสินว่าโสกราตีสผิด เพลโตเขียนว่าถ้าคะแนนเปลี่ยนข้างเพียง 30 เสียง โสกราตีสก็จะรอด เขาดื่มยาพิษตายในคุก ประโยคเรื่องชีวิตที่ไม่ได้ตรวจสอบมาจาก “คำแก้ต่าง” ที่เพลโตเขียน ประชาธิปไตยของเอเธนส์คือระบบที่ฆ่านักปรัชญาที่มีชื่อเสียงที่สุดของตัวเอง','In 399 BCE a jury of about 500, all male citizens over thirty, found Socrates guilty. Plato writes that if just 30 votes had gone the other way, Socrates would have been acquitted. He died in prison by drinking poison. The line about the unexamined life comes from Plato’s Apology. Athenian democracy put its most famous philosopher to death.'),
 o:[opt(X('ลงคะแนนว่าไม่ผิด','Vote not guilty'),S=>{meet16(S,'trial');S.trial16='no';fx({b:2,kn:2});return X('คุณแพ้ เวลาที่ใครถามว่าวันนั้นคุณโหวตอะไร คุณตอบได้โดยไม่ต้องหลบตา','You lose. Whenever anyone asks how you voted that day, you can answer without looking away.')}),
    opt(X('ลงคะแนนว่าผิด','Vote guilty'),S=>{meet16(S,'trial');S.trial16='yes';fx({p:2,b:-3});return X('คุณชนะ แต่พอได้ยินว่าเขาดื่มยาพิษอย่างใจเย็น คุณนอนไม่หลับไปหลายคืน','Your side wins. But when you hear how calmly he drank the poison, you lie awake for many nights.')})]}),
G16({id:'g16_plato',a:[14,80],cond:S=>S.rg==='ath'&&yr16(2410,2374)(S)&&(S.lit>=20||S.cls==='elite'),t:X('สวนของอะคาเดมัส','The grove of Academus'),
 x:X('นอกกำแพงเมือง ในสวนต้นมะกอกที่ชื่ออะคาเดเมีย ชายร่างใหญ่ชื่อเพลโตสอนว่าทุกสิ่งที่เราเห็นเป็นแค่เงาบนผนังถ้ำ ของจริงอยู่ที่อื่น','Outside the walls, in an olive grove called the Academy, a broad-shouldered man named Plato teaches that everything we see is only shadows on a cave wall; the real things are elsewhere.'),
 n:X('เพลโตตั้งสำนักอะคาเดเมียราว 387 ปีก่อนคริสตกาล ชื่อนี้มาจากวีรบุรุษอะคาเดมัส และกลายเป็นคำว่า academy เรื่องป้ายหน้าประตูที่ว่า “ห้ามผู้ไม่รู้เรขาคณิตเข้ามา” มาจากนักเขียนที่อยู่หลังเพลโตกว่าเจ็ดร้อยปี ✦ เพลโตรับนักเรียนหญิงอย่างน้อยสองคน','Plato founded the Academy around 387 BCE. The name came from the hero Academus and became our word academy. The sign over the door, “Let no one ignorant of geometry enter”, is reported by writers more than seven hundred years after Plato ✦. Plato took at least two women as pupils.'),
 o:[opt(X('ถามว่าแล้วเงาของคุณล่ะ','Ask about your own shadow'),S=>{meet16(S,'plato');fx({kn:5});return X('เพลโตตอบยาวมากจนตะวันตกดิน คุณเข้าใจแค่ครึ่งเดียว แต่ครึ่งนั้นติดอยู่ในหัวไปตลอดชีวิต','Plato answers at such length that the sun sets. You understand half of it, but that half stays with you for life.')}),
    opt(X('บอกว่าคุณชอบเงามากกว่า','Say you prefer the shadows'),S=>{meet16(S,'plato');fx({b:3});return X('นักเรียนคนหนึ่งชื่ออริสโตเติลหัวเราะออกมาเสียงดัง แล้วรีบทำหน้าขรึม','A pupil named Aristotle laughs out loud, then quickly looks serious.')})]}),
G16({id:'g16_diogenes',a:[8,85],cond:S=>['ath','cor'].includes(S.rg)&&yr16(2390,2363)(S),t:X('ตะเกียงกลางวัน','A lamp at noon'),
 x:X('ชายมอมแมมที่นอนในไหดินเผาใบใหญ่เดินถือตะเกียงกลางแดดเที่ยง เขาส่องหน้าทุกคนแล้วบอกว่ากำลังหา “มนุษย์” สักคน คนเรียกเขาว่าไดโอจีนีสหมา','A ragged man who sleeps in a huge clay jar walks through the noon sun holding a lamp. He shines it in everyone’s face and says he is looking for a human being. People call him Diogenes the Dog.'),
 n:X('ไดโอจีนีส (ราว 404–323 ปีก่อนคริสตกาล) คือนักปรัชญาสำนักซินิก ซึ่งมาจากคำว่า “หมา” เขาเชื่อว่าคนควรอยู่อย่างเรียบง่ายตามธรรมชาติ ไม่สนเงินหรือหน้าตาในสังคม เรื่องตะเกียงและเรื่องอื่นๆ ของเขาเกือบทั้งหมดมาจากหนังสือที่เขียนหลังเขาราวห้าร้อยปี ✦ เมื่อมีคนถามว่ามาจากไหน เขาตอบว่า “ข้าเป็นพลเมืองของโลก”','Diogenes (about 404–323 BCE) was a Cynic philosopher, from the Greek word for “dog”. He believed people should live simply and naturally, caring nothing for money or reputation. The lamp story and nearly all his anecdotes come from a book written some five hundred years after him ✦. Asked where he came from, he said, “I am a citizen of the world.”'),
 o:[opt(X('ยืนให้เขาส่องหน้า','Let him shine it in your face'),S=>{meet16(S,'diogenes');fx({b:3,kn:2});return X('เขาส่องอยู่นานแล้วส่ายหน้า “เกือบแล้ว” คุณไม่รู้ว่าควรดีใจหรือเสียใจ','He looks for a long time, then shakes his head: “Nearly.” You cannot decide whether to be pleased or hurt.')}),
    opt(X('ให้ขนมปังเขาก้อนหนึ่ง','Give him a loaf of bread'),S=>{meet16(S,'diogenes');fx({b:4,f:-1});return X('เขารับไปโดยไม่ขอบคุณ แล้วแบ่งครึ่งให้หมาข้างทาง','He takes it without thanks and shares half with a dog by the road.')})]}),
G16({id:'g16_alexander',a:[6,85],cond:S=>S.rg==='cor'&&yr16(2362,2359)(S),t:X('ถอยออกไปจากแดดหน่อย','Stand out of my sun'),
 x:X('กษัตริย์หนุ่มจากมาซิโดเนียชื่ออเล็กซานเดอร์มาที่โครินธ์ ทุกคนแย่งกันไปคำนับ ยกเว้นไดโอจีนีสที่นอนอาบแดดอยู่ อเล็กซานเดอร์เดินไปหาเขาและถามว่าอยากได้อะไร ไดโอจีนีสตอบว่า “ถอยออกไปจากแดดหน่อย”','A young king from Macedon named Alexander comes to Corinth. Everyone rushes to bow, except Diogenes, lying in the sun. Alexander goes to him and asks what he would like. Diogenes answers: “Stand a little out of my sun.”'),
 n:X('พลูทาร์กเล่าว่าอเล็กซานเดอร์ตอบว่า “ถ้าข้าไม่ใช่อเล็กซานเดอร์ ข้าก็อยากเป็นไดโอจีนีส” ✦ อเล็กซานเดอร์อายุราว 20 ปี ปีต่อมาเขาเริ่มเดินทัพที่จะพิชิตเปอร์เซียและไปถึงอินเดีย เขาตายที่บาบิโลนในปี 323 ปีก่อนคริสตกาล ปีเดียวกับที่ไดโอจีนีสตาย','Plutarch says Alexander replied, “If I were not Alexander, I would be Diogenes” ✦. Alexander was about twenty. The next year he began the march that would conquer Persia and reach India. He died in Babylon in 323 BCE, the same year as Diogenes.'),
 o:[opt(X('หัวเราะออกมาดังๆ','Laugh out loud'),S=>{meet16(S,'alexander');meet16(S,'diogenes');fx({b:4});return X('ทหารมาซิโดเนียหันมามองคุณ แต่กษัตริย์ก็หัวเราะด้วย คุณรอดไป','The Macedonian guards turn to look at you, but the king is laughing too, and you get away with it.')}),
    opt(X('คำนับกษัตริย์ให้ดี','Bow properly to the king'),S=>{meet16(S,'alexander');meet16(S,'diogenes');fx({p:2});return X('อเล็กซานเดอร์ไม่สนใจคุณเลยสักนิด สายตาเขามองไปทางตะวันออก','Alexander does not notice you at all. His eyes are on the east.')})]}),
G16({id:'g16_aristotle',a:[12,80],cond:S=>S.rg==='ath'&&yr16(2360,2349)(S),t:X('ครูที่สอนไปเดินไป','The teacher who walks as he teaches'),
 x:X('ที่โรงเรียนลีเซียม ชายชื่ออริสโตเติลเดินไปมาตามทางเดินมีหลังคาขณะสอน บนโต๊ะมีปลาหมึกผ่าครึ่ง เขาบอกว่าโลมาหายใจด้วยปอดและออกลูกเป็นตัวเหมือนวัว ไม่ใช่ปลา','At the Lyceum a man named Aristotle paces up and down a covered walk as he teaches. On a table lies an octopus cut in half. He says dolphins breathe with lungs and bear live young like cows: they are not fish.'),
 n:X('อริสโตเติลเปิดโรงเรียนลีเซียมในปี 335 ปีก่อนคริสตกาล ลูกศิษย์ของเขาถูกเรียกว่า “เพอริพาเทติก” ซึ่งอาจมาจากทางเดินมีหลังคา หรือจากนิสัยเดินสอน ✦ เขาเขียนเรื่องสัตว์กว่าห้าร้อยชนิด หลายเรื่องถูก เช่นเรื่องโลมา หลายเรื่องผิด เช่นว่าผู้หญิงมีฟันน้อยกว่าผู้ชาย เขาเคยเป็นครูของอเล็กซานเดอร์มหาราช','Aristotle opened the Lyceum in 335 BCE. His pupils were called Peripatetics, perhaps from the covered walk, perhaps from his habit of walking as he taught ✦. He wrote about more than five hundred kinds of animals, often rightly, as with dolphins, sometimes wrongly, as when he said women have fewer teeth than men. He had once been tutor to Alexander the Great.'),
 o:[opt(X('นับฟันของแม่ตัวเอง','Count your mother’s teeth'),S=>{meet16(S,'aristotle');fx({kn:4,b:2});return X('จำนวนเท่ากับของพ่อ คุณกลับไปบอกอริสโตเติล เขาจดไว้แต่ไม่แก้ตำรา','The same number as your father’s. You tell Aristotle; he notes it down but does not change his book.')}),
    opt(X('ช่วยผ่าปลาหมึก','Help dissect the octopus'),S=>{meet16(S,'aristotle');fx({kn:4,cr:1});return X('มือคุณเหม็นไปสามวัน แต่คุณรู้แล้วว่าปลาหมึกมีหัวใจมากกว่าหนึ่งดวง','Your hands stink for three days, but now you know an octopus has more than one heart.')})]}),
G16({id:'g16_hyphasis',a:[18,55],cond:S=>S.sex==='m'&&S.cls!=='slave'&&S.rg!=='spa'&&S.alx16&&yr16(2352,2350)(S),t:X('ริมแม่น้ำไฮฟาซิส','On the banks of the Hyphasis'),
 x:X('แปดปีแล้วที่คุณเดินทัพตามอเล็กซานเดอร์จากกรีก ผ่านเปอร์เซีย อียิปต์ จนถึงอินเดีย ฝนตกไม่หยุดมาเจ็ดสิบวัน รองเท้าเปื่อยหมด อเล็กซานเดอร์อยากข้ามแม่น้ำไปต่อ แต่นายทหารแก่ชื่อโคนัสลุกขึ้นพูดแทนทุกคนว่าพอแล้ว','For eight years you have marched behind Alexander from Greece through Persia and Egypt to India. It has rained for seventy days and every sandal has rotted. Alexander wants to cross the river and go on, but an old officer named Coenus stands up and says, for everyone, that it is enough.'),
 n:X('ในปี 326 ปีก่อนคริสตกาล ที่แม่น้ำไฮฟาซิส (แม่น้ำเบียสในอินเดียทุกวันนี้) ทหารของอเล็กซานเดอร์ไม่ยอมเดินต่อ ตามที่นักประวัติศาสตร์อาร์เรียนเล่า โคนัสเป็นคนพูดแทนกองทัพ อเล็กซานเดอร์ขังตัวอยู่ในเต็นท์สามวันก่อนยอมหันกลับ โคนัสตายไม่กี่วันหลังจากนั้น อาณาจักรของอเล็กซานเดอร์แผ่ภาษากรีกไปจนถึงอัฟกานิสถานและอินเดีย','In 326 BCE, at the Hyphasis (today’s Beas in India), Alexander’s soldiers refused to go on. According to the historian Arrian, Coenus spoke for the army. Alexander shut himself in his tent for three days before agreeing to turn back. Coenus died a few days later. Alexander’s conquests spread the Greek language as far as Afghanistan and India.'),
 o:[opt(X('ตะโกนเห็นด้วยกับโคนัส','Shout your agreement with Coenus'),S=>{meet16(S,'coenus');meet16(S,'alexander');fx({b:6,p:2});ms(X('เดินทัพไปถึงอินเดียกับอเล็กซานเดอร์','Marched to India with Alexander'));return X('ทหารร้องไห้ด้วยความดีใจเมื่อได้ยินว่าจะกลับบ้าน แต่ทางกลับผ่านทะเลทรายจะคร่าชีวิตคนมากกว่าการรบทั้งหมด','The soldiers weep with joy at the news of home, but the road back across the desert will kill more men than all the battles.')}),
    opt(X('เงียบ เผื่อกษัตริย์โกรธ','Keep quiet in case the king is angry'),S=>{meet16(S,'coenus');meet16(S,'alexander');fx({p:1});ms(X('เดินทัพไปถึงอินเดียกับอเล็กซานเดอร์','Marched to India with Alexander'));return X('สามวันต่อมา อเล็กซานเดอร์สร้างแท่นบูชาสิบสองแท่นริมแม่น้ำ แล้วสั่งให้หันกลับ','Three days later Alexander builds twelve altars by the river and gives the order to turn back.')})]}),
G16({id:'g16_epicurus',a:[14,85],cond:S=>S.rg==='ath'&&yr16(2330,2296)(S),t:X('สวนของเอพิคิวรัส','The Garden of Epicurus'),
 x:X('ในสวนผักหลังบ้านหลังหนึ่ง ชายชื่อเอพิคิวรัสกินขนมปังกับน้ำเปล่ากับเพื่อน ในกลุ่มมีผู้หญิงและทาสนั่งถกปรัชญาด้วย เขาบอกว่าไม่ต้องกลัวเทพเจ้าและความตาย ความสุขคือการไม่เจ็บปวดและมีเพื่อน','In a vegetable garden behind a house, a man named Epicurus eats bread and water with his friends. Women and slaves sit among them, talking philosophy. He says there is no need to fear the gods or death: happiness is freedom from pain, and friends.'),
 n:X('เอพิคิวรัสตั้งสำนัก “สวน” ในเอเธนส์ราว 306 ปีก่อนคริสตกาล และรับทั้งผู้หญิงและทาสเป็นลูกศิษย์ ซึ่งหายากมากในยุคนั้น เขาสอนว่า “ความตายไม่ใช่อะไรสำหรับเรา” เพราะเมื่อเรายังอยู่ ความตายยังไม่มา และเมื่อความตายมา เราก็ไม่อยู่แล้ว ทุกวันนี้คำว่า epicurean กลับหมายถึงคนชอบกินของอร่อย ซึ่งตรงข้ามกับชีวิตจริงของเขา','Epicurus founded his school, the Garden, in Athens around 306 BCE, and accepted women and slaves as pupils, which was very rare at the time. He taught that “death is nothing to us”: while we exist, death is not here, and when death is here, we no longer exist. Today “epicurean” means someone who loves fine food, the opposite of how he actually lived.'),
 o:[opt(X('นั่งลงกินขนมปังด้วย','Sit and share the bread'),S=>{meet16(S,'epicurus');fx({b:6,so:2});return X('ไม่มีใครถามว่าคุณเป็นใคร มาจากไหน หรือเป็นทาสหรือเปล่า','No one asks who you are, where you come from, or whether you are a slave.')}),
    opt(X('ถามว่าแล้วชีสล่ะ','Ask whether there is any cheese'),S=>{meet16(S,'epicurus');fx({b:4});return X('เอพิคิวรัสหัวเราะ ส่งหม้อชีสใบเล็กให้ แล้วบอกว่า “นี่แหละงานเลี้ยงของข้า”','Epicurus laughs, passes a little pot of cheese, and says, “This is my feast.”')})]}),
G16({id:'g16_pytheas',a:[8,85],cond:S=>S.rg==='mas'&&yr16(2352,2325)(S),t:X('ชายที่ไปถึงทะเลแข็ง','The man who reached the frozen sea'),
 x:X('พ่อค้าเรือชื่อพีเธียสกลับมาจากการเดินทางไปทางเหนือ เขาเล่าว่ามีเกาะที่ดวงอาทิตย์ไม่ตกในฤดูร้อน มีทะเลที่น้ำขึ้นลงสูงเท่าบ้านสองชั้น และไกลออกไปอีกคือทะเลที่ไม่ใช่น้ำไม่ใช่ดิน เหมือนแมงกะพรุน','A sea captain named Pytheas comes back from a voyage to the north. He tells of an island where the sun does not set in summer, of tides as high as a two-storey house, and beyond that a sea that is neither water nor land, like a jellyfish.'),
 n:X('พีเธียสแห่งมัสซาเลียเดินเรือรอบบริเตนราว 325 ปีก่อนคริสตกาล และเขียนถึงดินแดนชื่อ “ทูเล” ทางเหนือ หนังสือของเขาหายไป เรารู้จากนักเขียนรุ่นหลังที่หลายคนเรียกเขาว่าคนโกหก แต่สิ่งที่เขาเล่า เช่นพระอาทิตย์เที่ยงคืนและน้ำขึ้นลงสูง ตรงกับความจริงของทะเลเหนือ “ทะเลแมงกะพรุน” อาจเป็นน้ำแข็งที่เริ่มเกาะในทะเลหรือหมอกทะเล','Pytheas of Massalia sailed round Britain around 325 BCE and wrote of a northern land called Thule. His book is lost; we know it from later writers, many of whom called him a liar. Yet what he described, such as the midnight sun and great tides, matches the real North Sea. His “jellyfish sea” may have been forming sea ice or sea fog.'),
 o:[opt(X('เชื่อเขา','Believe him'),S=>{meet16(S,'pytheas');fx({kn:4,tr:2});return X('คุณฝันถึงทะเลแมงกะพรุนไปหลายปี','You dream of the jellyfish sea for years.')}),
    opt(X('หัวเราะว่าเขาโม้','Laugh that he is making it up'),S=>{meet16(S,'pytheas');fx({so:2});return X('สองพันปีต่อมา คนที่ไปถึงที่นั่นจะพบว่าเขาพูดจริง','Two thousand years later, people who go there will find he was telling the truth.')})]}),
G16({id:'g16_euclid',a:[10,80],cond:S=>S.rg==='ale'&&yr16(2330,2276)(S),t:X('ไม่มีถนนหลวง','No royal road'),
 x:X('ที่หอสมุดอเล็กซานเดรีย ครูชื่อยุคลิดเขียนรูปสามเหลี่ยมบนกระดานทราย กษัตริย์ปโตเลมีบ่นว่ามันยากเกินไป และถามว่ามีทางลัดไหม ยุคลิดตอบว่า “ไม่มีถนนหลวงสำหรับเรขาคณิต”','At the Library of Alexandria a teacher named Euclid draws triangles on a sand board. King Ptolemy complains it is too hard and asks whether there is a shortcut. Euclid answers: “There is no royal road to geometry.”'),
 n:X('“มูลบท” ของยุคลิด (ราว 300 ปีก่อนคริสตกาล) อาจเป็นตำราที่ถูกใช้สอนนานที่สุดในโลก นักเรียนยังเรียนจากมันมาจนถึงศตวรรษที่ 20 เรื่อง “ถนนหลวง” มาจากนักเขียนที่อยู่หลังเขาราวเจ็ดร้อยปี และมีอีกฉบับที่เล่าว่าเป็นคำพูดของนักคณิตศาสตร์อีกคนกับอเล็กซานเดอร์มหาราช ✦','Euclid’s Elements (about 300 BCE) may be the longest-used textbook in the world: students still learned from it into the 20th century. The “royal road” story comes from a writer some seven hundred years later, and another version gives the words to a different mathematician speaking to Alexander the Great ✦.'),
 o:[opt(X('ลองพิสูจน์เอง','Try the proof yourself'),S=>{meet16(S,'euclid');fx({kn:5});return X('สามวันต่อมาคุณพิสูจน์ได้ ยุคลิดบอกว่า “ดี ทีนี้ข้อต่อไป” มีอีกสี่ร้อยกว่าข้อ','Three days later you have it. Euclid says, “Good. Now the next one.” There are more than four hundred.')}),
    opt(X('ถามว่าเรียนแล้วได้อะไร','Ask what use it is'),S=>{meet16(S,'euclid');fx({b:1});return X('ยุคลิดหันไปสั่งทาสว่า “ให้เหรียญเขาหนึ่งเหรียญ เขาต้องได้กำไรจากทุกอย่างที่เรียน” ✦','Euclid tells a slave, “Give him a coin, since he must make a profit from what he learns.” ✦')})]}),
G16({id:'g16_aristarchus',a:[12,80],cond:S=>['ale','mil'].includes(S.rg)&&yr16(2305,2256)(S),t:X('โลกหมุนรอบดวงอาทิตย์','The Earth goes round the Sun'),
 x:X('นักดาราศาสตร์จากเกาะซามอสชื่ออริสตาร์คัสวัดเงาของดวงจันทร์ แล้วสรุปว่าดวงอาทิตย์ใหญ่กว่าโลกมาก ของใหญ่ไม่ควรหมุนรอบของเล็ก เขาจึงบอกว่าโลกต่างหากที่หมุนรอบดวงอาทิตย์ ทุกคนหัวเราะ','An astronomer from Samos named Aristarchus measures the Moon’s shadow and concludes that the Sun is far bigger than the Earth. A big thing should not circle a small one, he says, so it is the Earth that goes round the Sun. Everyone laughs.'),
 n:X('อริสตาร์คัส (ราว 310–230 ปีก่อนคริสตกาล) เสนอว่าโลกหมุนรอบดวงอาทิตย์ เกือบสองพันปีก่อนโคเปอร์นิคัส หนังสือเรื่องนี้ของเขาหายไป เรารู้เพราะอาร์คิมิดีสเขียนถึงไว้ คนส่วนใหญ่ไม่เชื่อ เพราะถ้าโลกเคลื่อนที่ ตำแหน่งของดวงดาวน่าจะเปลี่ยน ซึ่งมองด้วยตาเปล่าไม่เห็น เพราะดาวอยู่ไกลกว่าที่ใครคิด','Aristarchus (about 310–230 BCE) proposed that the Earth goes round the Sun, almost two thousand years before Copernicus. His book on it is lost; we know of it because Archimedes mentioned it. Most people did not believe him: if the Earth moved, the stars should shift, and to the naked eye they do not, because they are far more distant than anyone imagined.'),
 o:[opt(X('เชื่อเขา','Believe him'),S=>{meet16(S,'aristarchus');fx({kn:5,p:-1});return X('ทุกคนคิดว่าคุณบ้า คุณไม่สนใจ คืนนั้นคุณรู้สึกว่าพื้นใต้เท้ากำลังวิ่ง','Everyone thinks you are mad. You do not care. That night you feel the ground racing under your feet.')}),
    opt(X('หัวเราะกับคนอื่น','Laugh with the others'),S=>{meet16(S,'aristarchus');fx({so:2});return X('อีกสองพันปี คนจะหัวเราะกลับมาที่พวกคุณ','In two thousand years, people will laugh back at all of you.')})]}),
G16({id:'g16_erat',a:[10,80],cond:S=>S.rg==='ale'&&yr16(2265,2221)(S),t:X('วัดขนาดของโลก','Measuring the world'),
 x:X('หัวหน้าหอสมุดชื่อเอราทอสเทนีสได้ยินว่า ที่เมืองไซยีนทางใต้ ตอนเที่ยงวันกลางฤดูร้อน แสงอาทิตย์ส่องลงก้นบ่อพอดี วันเดียวกันที่อเล็กซานเดรีย เสายังมีเงา เขาให้คุณช่วยวัดมุมของเงานั้น','The head of the Library, Eratosthenes, has heard that at Syene in the south, at noon on midsummer’s day, the sun shines straight down to the bottom of a well. On the same day in Alexandria a pillar still casts a shadow. He asks you to help measure its angle.'),
 n:X('เอราทอสเทนีส (ราว 276–194 ปีก่อนคริสตกาล) พบว่าเงาที่อเล็กซานเดรียเป็นมุมราวหนึ่งในห้าสิบของวงกลม เมื่อคูณกับระยะทางถึงไซยีน (อัสวานทุกวันนี้) เขาได้เส้นรอบโลกราว 250,000 สตาดิอา ไม่มีใครรู้แน่ว่าสตาดิออนของเขายาวเท่าไร แต่ตัวเลขน่าจะคลาดจากความจริงเพียงไม่กี่เปอร์เซ็นต์ไปจนถึงราวร้อยละ 15 ชาวกรีกที่มีการศึกษารู้ว่าโลกกลมมาตั้งแต่สมัยอริสโตเติล','Eratosthenes (about 276–194 BCE) found the shadow at Alexandria was about one-fiftieth of a circle. Multiplying by the distance to Syene (today’s Aswan) gave a circumference of about 250,000 stadia. No one knows exactly how long his stadion was, but his figure was probably off by between a few percent and about 15%. Educated Greeks had known the Earth was round since Aristotle.'),
 o:[opt(X('วัดเงาอย่างละเอียด','Measure the shadow carefully'),S=>{meet16(S,'erat');fx({kn:5,cr:2});ms(X('ช่วยวัดขนาดของโลก','Helped measure the size of the Earth'));return X('มุมนั้นเล็กนิดเดียว แต่เมื่อคูณออกมา โลกใหญ่กว่าที่คุณเคยคิดไว้ทั้งชีวิต','The angle is tiny, but multiplied out, the world is bigger than you ever imagined.')}),
    opt(X('ถามว่าใครเดินนับระยะทาง','Ask who paced out the distance'),S=>{meet16(S,'erat');fx({kn:3});return X('เขาบอกว่าคนนับก้าวของกษัตริย์ คุณสงสัยว่าเท้าของพวกเขาเจ็บแค่ไหน','He says the king’s pacers. You wonder how much their feet hurt.')})]}),
G16({id:'g16_eureka',a:[10,80],cond:S=>S.rg==='syr'&&yr16(2275,2241)(S),t:X('ยูเรกา','Eureka'),
 x:X('ชายเปลือยกายวิ่งผ่านถนนในซีราคิวส์ ตะโกนว่า “ยูเรกา ยูเรกา” แปลว่า “เจอแล้ว” คนบอกว่าเป็นอาร์คิมิดีส เขาเพิ่งนึกออกในอ่างอาบน้ำว่าจะพิสูจน์ได้อย่างไรว่ามงกุฎทองของกษัตริย์ผสมเงินหรือเปล่า','A naked man runs down a street in Syracuse shouting “Eureka, eureka!”: “I have found it!” People say it is Archimedes. In the bath he has just worked out how to prove whether the king’s gold crown was mixed with silver.'),
 n:X('เรื่องอ่างอาบน้ำมาจากวิทรูเวียส นักเขียนชาวโรมันที่อยู่หลังอาร์คิมิดีสเกือบสองร้อยปี ✦ แต่อาร์คิมิดีสเขียนหนังสือเรื่องแรงลอยตัวจริง กฎที่ว่าของที่จมในน้ำจะถูกดันขึ้นเท่ากับน้ำหนักของน้ำที่มันแทนที่ ยังเรียกว่าหลักของอาร์คิมิดีส','The bath story comes from Vitruvius, a Roman writer nearly two hundred years after Archimedes ✦. But Archimedes really did write a book on floating bodies, and the rule that an object in water is pushed up by the weight of the water it displaces is still called Archimedes’ principle.'),
 o:[opt(X('วิ่งไปเอาผ้าคลุมให้เขา','Run to bring him a cloak'),S=>{meet16(S,'archimedes');fx({so:2,b:3});return X('เขาไม่สนใจผ้าคลุม แต่จับแขนคุณแล้วอธิบายเรื่องน้ำล้นอ่างจนคุณเข้าใจ','He ignores the cloak, grabs your arm and explains the overflowing water until you understand.')}),
    opt(X('หัวเราะจนท้องแข็ง','Laugh until your sides ache'),S=>{meet16(S,'archimedes');fx({b:4});return X('ทั้งเมืองหัวเราะไปอีกหลายปี และเล่าต่อกันมาอีกสองพันกว่าปี','The whole city laughs for years, and people go on telling it for two thousand more.')})]}),
G16({id:'g16_circles',a:[8,85],cond:S=>S.rg==='syr'&&yr16(2238,2236)(S),t:X('อย่าเหยียบวงกลมของข้า','Do not disturb my circles'),
 x:X('สองปีแล้วที่กองทัพโรมันล้อมซีราคิวส์ เครื่องจักรของอาร์คิมิดีสยกเรือโรมันขึ้นจากน้ำแล้วปล่อยให้คว่ำ แต่คืนนี้ทหารโรมันปีนกำแพงเข้ามาได้ระหว่างที่เมืองจัดงานเทศกาล','For two years the Roman army has besieged Syracuse. Archimedes’ machines have lifted Roman ships out of the water and tipped them over. But tonight, during a festival, Roman soldiers climb over the wall.'),
 n:X('ซีราคิวส์แตกในปี 212 ปีก่อนคริสตกาล นายพลมาร์เซลลัสสั่งไม่ให้ทำร้ายอาร์คิมิดีส แต่ทหารคนหนึ่งฆ่าเขา ตำนานเล่าว่าเขากำลังวาดรูปเรขาคณิตบนทราย และบอกทหารว่า “อย่าเหยียบวงกลมของข้า” ✦ เรื่องเครื่องจักรยกเรือมาจากนักประวัติศาสตร์โพลีเบียส ส่วนเรื่องกระจกเผาเรือเป็นตำนานยุคหลัง ✦','Syracuse fell in 212 BCE. The general Marcellus ordered that Archimedes be spared, but a soldier killed him. Legend says he was drawing geometry in the sand and told the soldier, “Do not disturb my circles” ✦. The ship-lifting machines are described by the historian Polybius; the mirrors that burned ships are a later legend ✦.'),
 o:[opt(X('หนีลงห้องใต้ดิน','Flee to the cellar'),S=>{meet16(S,'archimedes');fx({b:-8,f:-6});return X('รุ่งเช้า คุณได้ยินว่าชายแก่ที่วาดวงกลมบนทรายถูกฆ่าตาย','At dawn you hear that the old man who drew circles in the sand has been killed.')}),
    opt(X('วิ่งไปเตือนอาร์คิมิดีส','Run to warn Archimedes'),S=>{meet16(S,'archimedes');if(rnd()<.3){fx({h:-15});S.inj=1;return X('คุณถูกดาบฟันที่แขนก่อนจะไปถึง','A sword cuts your arm before you get there.')}fx({b:-6,so:2});return X('คุณไปถึงช้าไป เหลือแต่รูปวงกลมบนทรายที่ถูกเหยียบจนเลือน','You arrive too late. All that is left are circles in the sand, trampled to nothing.')})]})
];

GUMP16.push(
G16({id:'g16_koroibos',a:[6,85],cond:yr16(2802,2800),t:X('การแข่งวิ่งครั้งแรก','The first race'),
 x:X('ที่ทุ่งริมแม่น้ำในโอลิมเปีย ชายหนุ่มวิ่งแข่งกันระยะหนึ่งสตาดิออน ราว 190 เมตร คนชนะคือพ่อครัวจากเอลิสชื่อโคโรอิบอส รางวัลคือกิ่งมะกอก','On the meadow by the river at Olympia young men race the length of one stadion, about 190 metres. The winner is a cook from Elis named Koroibos. His prize is an olive branch.'),
 n:X('ชาวกรีกนับปีจากโอลิมปิกครั้งแรกในปี 776 ปีก่อนคริสตกาล และรายชื่อผู้ชนะเริ่มที่โคโรอิบอส แต่รายชื่อนี้ถูกรวบรวมขึ้นหลายร้อยปีต่อมา นักประวัติศาสตร์จึงไม่แน่ใจว่าปีนั้นถูกต้อง ✦ ในช่วงแรกมีการแข่งแค่วิ่งระยะสั้นรายการเดียว คำว่า stadium มาจาก “สตาดิออน”','Greeks counted years from the first Olympics in 776 BCE, and the list of victors begins with Koroibos, but the list was compiled centuries later, so historians are not sure of the date ✦. At first there was just one event, a short sprint. The word stadium comes from stadion.'),
 o:[opt(X('ร้องเชียร์จนเสียงแหบ','Cheer yourself hoarse'),S=>{meet16(S,'koroibos');fx({b:4,so:1});return X('เขาวิ่งผ่านคุณไปเร็วจนคุณได้ยินแค่เสียงเท้าเปล่ากระทบดิน','He flashes past so fast you hear only bare feet on the earth.')}),
    opt(X('ถามว่าพ่อครัววิ่งเร็วได้อย่างไร','Ask how a cook runs so fast'),S=>{meet16(S,'koroibos');fx({kn:2,b:2});return X('เขาหัวเราะว่าวิ่งไล่แพะที่หนีออกจากครัวมาทั้งชีวิต','He laughs that he has spent his life chasing goats that escaped from the kitchen.')})]}),
G16({id:'g16_hesiod',a:[10,85],cond:S=>!['syr','mas','ale'].includes(S.rg)&&yr16(2740,2705)(S),t:X('กวีชาวนา','The farmer-poet'),
 x:X('ที่งานแข่งขันกวีในเมืองคัลคิส ชาวนาจากหมู่บ้านอัสครา ชื่อเฮสิโอด ชนะรางวัลหม้อสามขา เขาท่องกลอนเรื่องงานในไร่ตามฤดู และสอนว่าคนที่ขยันไม่ต้องอดอยาก','At a poetry contest in Chalcis a farmer from the village of Ascra, named Hesiod, wins a bronze tripod. He recites verses on the farm work of each season, and teaches that those who work hard need not go hungry.'),
 n:X('เฮสิโอดมีชีวิตราว 700 ปีก่อนคริสตกาล ใน “งานและวัน” เขาเล่าเองว่าชนะหม้อสามขาที่คัลคิส และบ่นเรื่องพี่ชายที่โกงมรดก นี่คือหนึ่งในครั้งแรกในวรรณกรรมยุโรปที่กวีเล่าเรื่องชีวิตตัวเอง','Hesiod lived around 700 BCE. In Works and Days he tells us himself that he won a tripod at Chalcis, and grumbles about a brother who cheated him of his inheritance: one of the first times in European literature that a poet speaks of his own life.'),
 o:[opt(X('จำกลอนเรื่องฤดูไถนา','Memorise his verses on ploughing time'),S=>{meet16(S,'hesiod');fx({kn:3,f:2});return X('“เมื่อได้ยินเสียงนกกระเรียนร้องจากฟ้า ก็ถึงเวลาไถ” คุณใช้กลอนนี้จับฤดูไปทั้งชีวิต','“When you hear the crane calling from the clouds, it is time to plough.” You set your seasons by it all your life.')}),
    opt(X('ถามเรื่องพี่ชายของเขา','Ask about his brother'),S=>{meet16(S,'hesiod');fx({b:3});return X('เขาบ่นยาวกว่ากลอนที่ท่องเสียอีก','He complains for longer than the poem.')})]}),
G16({id:'g16_archilochus',a:[12,85],cond:S=>['mil','les','cor','ath'].includes(S.rg)&&yr16(2700,2665)(S),t:X('ทหารที่ทิ้งโล่','The soldier who threw away his shield'),
 x:X('ทหารรับจ้างจากเกาะพารอสชื่ออาร์คิโลคัสนั่งดื่มในท่าเรือ แล้วร้องเพลงที่เขาแต่งเองว่าเขาทิ้งโล่หนีในการรบ ช่างหัวมัน เดี๋ยวก็ซื้อใหม่ได้ ทุกคนอ้าปากค้าง','A mercenary from Paros named Archilochus sits drinking at the harbour and sings a song of his own about throwing away his shield to run from a battle. To hell with it, he sings; he can buy another. Everyone gapes.'),
 n:X('อาร์คิโลคัส (ราว 680–645 ปีก่อนคริสตกาล) เป็นกวีกรีกคนแรกๆ ที่เขียนเรื่องความรู้สึกของตัวเองแทนเรื่องวีรบุรุษ ว่ากันว่าชาวสปาร์ตาห้ามบทกวีเรื่องทิ้งโล่ของเขา ✦ ส่วนอีกประโยคที่มีชื่อเสียงว่า “หมาจิ้งจอกรู้หลายเรื่อง แต่เม่นรู้เรื่องใหญ่เรื่องเดียว” ก็เป็นของเขา','Archilochus (about 680–645 BCE) was among the first Greek poets to write of his own feelings rather than heroes. The Spartans were said to have banned his shield poem ✦. Another famous line, “The fox knows many things, but the hedgehog knows one big thing”, is his too.'),
 o:[opt(X('หัวเราะและร้องตาม','Laugh and sing along'),S=>{meet16(S,'archilochus');fx({b:4});return X('ผู้ใหญ่ดุคุณ แต่ทั้งท่าเรือร้องเพลงนี้ไปอีกหลายเดือน','The grown-ups scold you, but the whole harbour sings it for months.')}),
    opt(X('บอกว่าเขาไม่มีเกียรติ','Tell him he has no honour'),S=>{meet16(S,'archilochus');fx({p:2});return X('เขาแต่งกลอนล้อคุณทันทีสามบรรทัด ทุกคนจำได้ยกเว้นคุณ','He makes up three lines mocking you on the spot. Everyone remembers them except you.')})]}),
G16({id:'g16_periander',a:[8,85],cond:S=>S.rg==='cor'&&yr16(2645,2615)(S),t:X('นักร้องกับโลมา','The singer and the dolphin'),
 x:X('ที่ราชสำนักของเพเรียนเดอร์ ผู้ปกครองโครินธ์ นักร้องชื่ออาริออนเล่าว่าลูกเรือจะฆ่าเขาเพื่อเอาเงิน เขาขอร้องเพลงเป็นครั้งสุดท้าย แล้วกระโดดลงทะเล และโลมาก็แบกเขามาส่งถึงฝั่ง','At the court of Periander, ruler of Corinth, the singer Arion tells how the sailors meant to kill him for his money. He asked to sing one last song, leapt into the sea, and a dolphin carried him ashore.'),
 n:X('เฮโรโดตัสเล่าเรื่องอาริออนกับโลมา ✦ เพเรียนเดอร์ปกครองโครินธ์ราว 627–587 ปีก่อนคริสตกาล บางคนนับเขาเป็นหนึ่งในปราชญ์ทั้งเจ็ด บางคนว่าเป็นทรราชที่โหดร้าย ในยุคนี้ “ทรราช” หมายถึงคนที่ยึดอำนาจโดยไม่ได้สืบทอด ไม่จำเป็นต้องเป็นคนเลวเสมอไป','Herodotus tells the story of Arion and the dolphin ✦. Periander ruled Corinth around 627–587 BCE; some counted him among the Seven Sages, others called him a cruel tyrant. In this age a “tyrant” simply meant someone who seized power rather than inheriting it, not necessarily a wicked one.'),
 o:[opt(X('เชื่อเรื่องโลมา','Believe the dolphin story'),S=>{meet16(S,'periander');fx({b:4});return X('ทุกครั้งที่เห็นโลมาหลังจากนั้น คุณร้องเพลงให้มันฟัง','Every time you see dolphins after that, you sing to them.')}),
    opt(X('ถามว่าลูกเรือเป็นอย่างไรต่อ','Ask what happened to the sailors'),S=>{meet16(S,'periander');fx({kn:2});return X('เพเรียนเดอร์ยิ้มเย็นๆ แล้วบอกว่า “ถูกจับได้” คุณไม่ถามต่อ','Periander smiles coldly and says, “They were caught.” You do not ask more.')})]}),
G16({id:'g16_pittacus',a:[16,85],cond:S=>S.rg==='les'&&yr16(2615,2603)(S),t:X('กฎหมายคนเมา','The law for drunks'),
 x:X('ปิตตาคัส ผู้ที่ชาวมิทิลีนีเลือกให้ปกครองเพื่อหยุดสงครามกลางเมือง ออกกฎหมายใหม่: ใครทำผิดตอนเมา ต้องรับโทษเป็นสองเท่าของตอนไม่เมา','Pittacus, chosen by the people of Mytilene to rule and end their civil strife, makes a new law: anyone who commits a crime while drunk is punished twice as hard as if sober.'),
 n:X('อริสโตเติลเขียนถึงกฎหมายนี้ของปิตตาคัส และอธิบายว่าคนเมาก่อเรื่องบ่อยกว่า กฎหมายจึงสนใจประโยชน์ต่อบ้านเมืองมากกว่าความเห็นใจคนเมา ปิตตาคัสเป็นหนึ่งในปราชญ์ทั้งเจ็ด และลงจากอำนาจเองหลังสิบปี ซึ่งหายากมากสำหรับผู้ปกครองทุกยุค','Aristotle mentions this law of Pittacus, explaining that drunks cause more trouble, so the law looked to the public good rather than sympathy for the drunk. Pittacus was one of the Seven Sages, and stepped down of his own accord after ten years, rare for rulers in any age.'),
 o:[opt(X('เห็นด้วย','Agree'),S=>{meet16(S,'pittacus');fx({p:2,so:1});return X('งานเลี้ยงในเมืองเงียบลงทันตา ร้านเหล้าบ่น','The city’s parties grow suddenly quieter, and the wine-sellers grumble.')}),
    opt(X('บอกว่าคนเมาควรได้รับความเห็นใจ','Say drunks deserve sympathy'),S=>{meet16(S,'pittacus');fx({kn:2});return X('ปิตตาคัสตอบว่า “ความเห็นใจไม่ได้ซ่อมหัวที่แตก”','Pittacus replies, “Sympathy does not mend a broken head.”')})]}),
G16({id:'g16_aesop',a:[6,80],cond:S=>S.rg==='mil'&&yr16(2620,2580)(S),t:X('ทาสเล่านิทาน','The slave who tells fables'),
 x:X('ทาสหน้าตาแปลกๆ คนหนึ่งเล่านิทานให้เด็กๆ ฟังที่ท่าเรือ เรื่องหมาจิ้งจอกกับองุ่นเปรี้ยว เรื่องเต่ากับกระต่าย ทุกเรื่องจบด้วยบทเรียนที่ทำให้ผู้ใหญ่ที่ฟังอยู่หน้าแดง เขาชื่ออีสป','An odd-looking slave tells stories to the children at the harbour: the fox and the sour grapes, the tortoise and the hare. Every one ends with a lesson that makes the listening grown-ups blush. His name is Aesop.'),
 n:X('เฮโรโดตัสบอกว่าอีสปเป็นทาสบนเกาะซามอสใกล้มิเลทัส ราว 600 ปีก่อนคริสตกาล นอกจากนั้นเรื่องชีวิตของเขาเกือบทั้งหมดเป็นตำนาน ✦ และนิทานหลายเรื่องที่ใช้ชื่อเขาถูกแต่งขึ้นหลังเขาหลายร้อยปี นิทานอีสปเป็นหนังสือที่เด็กไทยหลายรุ่นได้อ่าน','Herodotus says Aesop was a slave on Samos, near Miletus, around 600 BCE. Almost everything else about his life is legend ✦, and many fables under his name were written centuries later. Aesop’s fables have been read by generations of Thai children.'),
 o:[opt(X('ขอฟังอีกเรื่อง','Beg for another story'),S=>{meet16(S,'aesop');fx({kn:2,b:3});return X('เขาเล่าเรื่องมดกับจั๊กจั่น แล้วมองไปที่เจ้านายของเขาที่นั่งเฉยๆ อยู่ในร่ม','He tells of the ant and the cicada, glancing at his master lounging in the shade.')}),
    opt(X('ถามว่าทำไมเขายังเป็นทาส ทั้งที่ฉลาดขนาดนี้','Ask why someone so clever is still a slave'),S=>{meet16(S,'aesop');fx({kn:3});return X('เขาตอบด้วยนิทานเรื่องหมาป่ากับหมาบ้านที่ใส่ปลอกคอ คุณคิดถึงมันไปหลายวัน','He answers with the fable of the wolf and the collared dog. You think about it for days.')})]}),
G16({id:'g16_anaximander',a:[10,80],cond:S=>S.rg==='mil'&&yr16(2590,2550)(S),t:X('แผนที่โลกแผ่นแรก','The first map of the world'),
 x:X('ลูกศิษย์ของทาลีสชื่ออแนกซิแมนเดอร์ วาดแผนที่โลกทั้งใบตามที่เขาจินตนาการ เป็นวงกลม มีทะเลของเราอยู่ตรงกลาง และมหาสมุทรล้อมรอบ เขาบอกว่าโลกลอยอยู่กลางอากาศโดยไม่ต้องมีอะไรค้ำ','Thales’ pupil Anaximander draws a map of the whole world as he imagines it: a circle, with our sea in the middle and Ocean all around. He says the Earth floats in the middle of everything with nothing holding it up.'),
 n:X('นักเขียนกรีกยุคหลังบอกว่าอแนกซิแมนเดอร์ (ราว 610–546 ปีก่อนคริสตกาล) เป็นคนแรกที่กล้าวาดแผนที่โลก ความคิดว่าโลกลอยอยู่ได้โดยไม่มีอะไรรองรับเป็นก้าวใหญ่มาก เขายังเสนอว่ามนุษย์คนแรกเกิดจากสัตว์ที่อยู่ในน้ำ','Later Greek writers say Anaximander (about 610–546 BCE) was the first to dare draw a map of the world. His idea that the Earth hangs unsupported was a huge leap. He also suggested that the first humans came from creatures living in water.'),
 o:[opt(X('ชี้หาบ้านของคุณบนแผนที่','Find your home on the map'),S=>{meet16(S,'anaximander');fx({kn:3,tr:2});return X('บ้านของคุณเป็นจุดเล็กนิดเดียวข้างทะเล คุณเพิ่งรู้ว่าโลกใหญ่แค่ไหน','Your home is a tiny dot beside the sea. For the first time you see how big the world is.')}),
    opt(X('ถามว่าทำไมโลกไม่ตก','Ask why the Earth does not fall'),S=>{meet16(S,'anaximander');fx({kn:4});return X('เขาตอบว่าเพราะไม่มีเหตุผลที่จะตกไปทางไหนมากกว่าทางอื่น คุณมึนไปทั้งวัน','He says there is no reason for it to fall one way rather than another. Your head spins all day.')})]}),
G16({id:'g16_phye',a:[8,85],cond:S=>S.rg==='ath'&&yr16(2583,2578)(S),t:X('เทพีอะธีนาบนรถม้า','Athena in a chariot'),
 x:X('รถม้าคันหนึ่งแล่นเข้าเมือง บนรถมีหญิงร่างสูงใหญ่ในชุดเกราะเทพีอะธีนา คนป่าวประกาศว่าเทพีพาปีซิสตราตัสกลับมาปกครองเอเธนส์ด้วยตัวเอง ชาวเมืองหลายคนคุกเข่ากราบ','A chariot drives into the city carrying a very tall woman in the armour of Athena. Heralds cry that the goddess herself is bringing Peisistratus back to rule Athens. Many people kneel.'),
 n:X('เฮโรโดตัสเล่าว่าหญิงคนนั้นชื่อฟีเอ เป็นหญิงชาวบ้านที่สูงราว 1.8 เมตร และเขาเองบ่นว่าเป็นกลอุบายที่โง่ที่สุดที่เคยได้ยิน ✦ ปีซิสตราตัสปกครองเอเธนส์เป็นทรราชหลายครั้งระหว่างราว 561–527 ปีก่อนคริสตกาล และว่ากันว่าเป็นคนแรกที่ให้รวบรวมบทกวีของโฮเมอร์เป็นลายลักษณ์อักษร ✦','Herodotus says the woman was named Phye, a village woman about 1.8 metres tall, and grumbles that it was the silliest trick he ever heard of ✦. Peisistratus ruled Athens as tyrant several times between about 561 and 527 BCE, and is said to have had Homer’s poems written down ✦.'),
 o:[opt(X('คุกเข่าตามคนอื่น','Kneel with the others'),S=>{meet16(S,'phye');fx({b:1,p:1});return X('หลายปีต่อมา คุณได้ยินว่าเทพีขายดอกไม้อยู่ในตลาด','Years later you hear that the goddess sells garlands in the market.')}),
    opt(X('ตะโกนว่า “นั่นมันฟีเอขายดอกไม้”','Shout, “That’s Phye the flower-seller!”'),S=>{meet16(S,'phye');fx({so:2,p:-1});return X('คนรอบข้างหัวเราะ แต่ทหารของปีซิสตราตัสจำหน้าคุณได้','People around you laugh, but Peisistratus’ guards remember your face.')})]}),
G16({id:'g16_cleisthenes',a:[16,85],cond:S=>S.rg==='ath'&&S.cls!=='slave'&&yr16(2533,2531)(S),t:X('สิบเผ่าใหม่','Ten new tribes'),
 x:X('ไคลส์ธีนีสประกาศว่าต่อไปนี้ชาวเอเธนส์จะไม่ถูกแบ่งตามตระกูลเก่าแก่อีก ทุกหมู่บ้านถูกจัดใหม่เป็นสิบเผ่า แต่ละเผ่ารวมคนจากเมือง ชายฝั่ง และภูเขา และทุกเผ่าส่งคนห้าสิบคนเข้าสภา','Cleisthenes announces that Athenians will no longer be grouped by the old noble clans. Every village is reorganised into ten tribes, each mixing people from the city, the coast and the hills, and each sends fifty men to the council.'),
 n:X('การปฏิรูปของไคลส์ธีนีสในปี 508–507 ปีก่อนคริสตกาลมักถูกนับเป็นจุดเริ่มต้นของประชาธิปไตยเอเธนส์ การจัดเผ่าใหม่ทำให้ตระกูลขุนนางคุมเสียงในพื้นที่ของตัวเองยากขึ้น ชาวเอเธนส์ใช้ชื่อหมู่บ้านต่อท้ายชื่อแทนชื่อตระกูล','Cleisthenes’ reforms of 508–507 BCE are usually counted as the start of Athenian democracy. Mixing the tribes made it harder for noble families to control the votes of their home districts. Athenians began to add their village’s name to their own instead of their clan’s.'),
 o:[opt(X('ไปลงชื่อที่หมู่บ้าน','Go and register in your village'),S=>{meet16(S,'cleisthenes');fx({p:2,so:2});return X('ตอนนี้คุณมีเพื่อนร่วมเผ่าเป็นคนจากภูเขาที่คุณไม่เคยรู้จักมาก่อน','Now your tribesmen include hill people you had never met.')}),
    opt(X('บ่นว่าระบบเก่าดีกว่า','Grumble that the old ways were better'),S=>{meet16(S,'cleisthenes');fx({b:1});return X('ผู้เฒ่าในตระกูลเก่าเห็นด้วยกับคุณ แต่ไม่มีใครฟังพวกเขาแล้ว','The elders of the old clans agree with you, but no one listens to them any more.')})]}),
G16({id:'g16_hiero',a:[10,85],cond:S=>S.rg==='syr'&&yr16(2503,2494)(S),t:X('กวีในราชสำนัก','Poets at court'),
 x:X('ไฮเอโร ผู้ปกครองซีราคิวส์ เชิญกวีที่ดีที่สุดในโลกกรีกมาอยู่ในวัง ทั้งพินดาร์ ผู้แต่งเพลงสรรเสริญผู้ชนะกีฬา และเอสคิลัส ผู้แต่งละครจากเอเธนส์','Hiero, ruler of Syracuse, invites the finest poets of the Greek world to his palace: Pindar, who writes songs for athletic victors, and Aeschylus, the playwright from Athens.'),
 n:X('พินดาร์แต่งบทเพลงฉลองชัยชนะของไฮเอโรในการแข่งม้าที่โอลิมเปียในปี 476 ปีก่อนคริสตกาล และเอสคิลัสเดินทางมาซิซิลีหลายครั้ง และตายที่นั่นในปี 456 ปีก่อนคริสตกาล ตำนานเล่าว่านกอินทรีทิ้งเต่าลงบนหัวล้านของเขา ✦','Pindar wrote an ode for Hiero’s horse-race victory at Olympia in 476 BCE, and Aeschylus came to Sicily more than once and died there in 456 BCE. Legend says an eagle dropped a tortoise on his bald head ✦.'),
 o:[opt(X('ฟังพินดาร์ร้องเพลง','Listen to Pindar sing'),S=>{meet16(S,'hiero');fx({b:3,so:1});return X('“น้ำคือสิ่งที่ดีที่สุด” เขาร้องขึ้นต้น ทั้งที่ทุกคนในงานกำลังดื่มเหล้า','“Best of all things is water,” he begins, while everyone at the feast is drinking wine.')}),
    opt(X('ถามเอสคิลัสว่าเคยรบจริงไหม','Ask Aeschylus whether he really fought'),S=>{meet16(S,'hiero');fx({kn:2});return X('เขาเงียบไปนาน แล้วเล่าเรื่องพี่ชายที่ถูกตัดมือที่มาราธอน','He is silent a long time, then tells of his brother, whose hand was cut off at Marathon.')})]}),
G16({id:'g16_phidias',a:[8,85],cond:yr16(2465,2450),t:X('เทพซุสในโรงงาน','Zeus in the workshop'),
 x:X('ที่โอลิมเปีย ในโรงงานหลังวิหาร ช่างชื่อฟีเดียสกำลังสร้างรูปเทพซุสนั่งบนบัลลังก์ สูงเกือบชนหลังคา ผิวทำจากงาช้าง เสื้อทำจากทองคำ ลูกมือยื่นถ้วยดินเผาให้เขาดื่มน้ำ','At Olympia, in a workshop behind the temple, a sculptor named Phidias is building a seated Zeus so tall his head nearly touches the roof, with skin of ivory and robes of gold. An assistant hands him a clay cup of water.'),
 n:X('รูปปั้นซุสที่โอลิมเปียสูงราว 12–13 เมตร เป็นหนึ่งในเจ็ดสิ่งมหัศจรรย์ของโลกยุคโบราณ และหายไปหมดแล้ว ในทศวรรษ 1950 นักโบราณคดีขุดพบโรงงานของฟีเดียส พร้อมแม่พิมพ์ดินเผาสำหรับขึ้นรูปทอง และถ้วยใบเล็กที่เขียนไว้ใต้ก้นว่า “ฉันเป็นของฟีเดียส”','The statue of Zeus at Olympia stood about 12–13 metres tall, one of the Seven Wonders of the ancient world; it is entirely lost. In the 1950s archaeologists excavated Phidias’ workshop, finding clay moulds for shaping the gold and a small cup inscribed underneath: “I belong to Pheidias.”'),
 o:[opt(X('ช่วยล้างถ้วย','Help wash the cups'),S=>{meet16(S,'phidias');fx({cr:2,b:3});return X('คุณล้างถ้วยใบเล็กที่เขียนชื่อเขา โดยไม่รู้ว่าอีกสองพันสี่ร้อยปีจะมีคนขุดมันขึ้นมา','You wash the little cup with his name on it, not knowing it will be dug up two thousand four hundred years later.')}),
    opt(X('ถามว่าถ้าซุสลุกขึ้นยืนจะเป็นอย่างไร','Ask what happens if Zeus stands up'),S=>{meet16(S,'phidias');fx({kn:2,b:2});return X('ฟีเดียสหัวเราะว่าหลังคาจะพัง นักเขียนรุ่นหลังก็บ่นเรื่องเดียวกันนี้','Phidias laughs that the roof would come off. Later writers made the same complaint.')})]}),
G16({id:'g16_kyniska',a:[8,85],cond:yr16(2421,2417),t:X('ผู้หญิงที่ชนะโอลิมปิก','The woman who won at Olympia'),
 x:X('ที่โอลิมเปีย ผู้ประกาศขานชื่อผู้ชนะการแข่งรถม้าสี่ตัว: คีนิสกา เจ้าหญิงแห่งสปาร์ตา เธอไม่ได้ลงแข่งเอง เพราะผู้หญิงแข่งไม่ได้ แต่ม้าเป็นของเธอ และเธอเป็นคนเลือกและฝึกมันเอง','At Olympia the herald calls the winner of the four-horse chariot race: Kyniska, princess of Sparta. She did not race herself, since women may not compete, but the horses are hers, and she chose and trained them herself.'),
 n:X('คีนิสกาชนะการแข่งรถม้าที่โอลิมเปียในปี 396 และ 392 ปีก่อนคริสตกาล เป็นผู้หญิงคนแรกที่มีชื่อในรายชื่อผู้ชนะโอลิมปิก ในการแข่งรถม้า ผู้ชนะคือเจ้าของม้า ไม่ใช่คนขับ จารึกที่ฐานรูปปั้นของเธอที่โอลิมเปียยังเหลืออยู่','Kyniska won the chariot race at Olympia in 396 and 392 BCE, the first woman in the list of Olympic victors. In chariot racing the owner of the horses, not the driver, was the winner. The inscription from the base of her statue at Olympia survives.'),
 o:[opt(X('โห่ร้องให้เธอ','Cheer for her'),S=>{meet16(S,'kyniska');fx({b:4,so:1});return X('ผู้ชายบางคนหน้าบึ้ง แต่ม้าของเธอวิ่งเร็วกว่าม้าของพวกเขาทุกตัว','Some of the men scowl, but her horses were faster than all of theirs.')}),
    opt(X('สงสัยว่าวันหนึ่งผู้หญิงจะได้ลงแข่งเองไหม','Wonder whether women will ever compete themselves'),S=>{meet16(S,'kyniska');fx({kn:2,b:2});return X('อีกสองพันกว่าปี ผู้หญิงจะได้ลงแข่งโอลิมปิกเป็นครั้งแรก','In a little over two thousand years, women will compete at the Olympics for the first time.')})]}),
G16({id:'g16_clouds',a:[10,85],cond:S=>S.rg==='ath'&&yr16(2449,2447)(S),t:X('ละครเรื่องเมฆ','The play called The Clouds'),
 x:X('ในละครตลกของอริสโตฟานีส นักแสดงใส่หน้ากากเหมือนโสกราตีสห้อยอยู่ในตะกร้ากลางอากาศ พูดเรื่องไร้สาระว่ายุงส่งเสียงทางก้น ทั้งโรงละครหัวเราะ แล้วโสกราตีสตัวจริงก็ลุกขึ้นยืนในหมู่คนดู','In Aristophanes’ comedy an actor in a Socrates mask hangs in a basket in mid-air, explaining nonsense about gnats humming through their bottoms. The whole theatre roars, and then the real Socrates stands up in the audience.'),
 n:X('“เมฆ” แสดงในปี 423 ปีก่อนคริสตกาล และล้อโสกราตีสว่าเป็นครูที่สอนให้คนเถียงเอาชนะ ในคำแก้ต่างที่เพลโตเขียน โสกราตีสบอกว่าละครเรื่องนี้ทำให้คนเกลียดเขามาหลายปีก่อนถูกฟ้อง เรื่องที่เขาลุกขึ้นยืนให้คนดูเทียบหน้ากับหน้าจริงมาจากนักเขียนยุคหลัง ✦','The Clouds was staged in 423 BCE and mocked Socrates as a teacher of trick arguments. In Plato’s Apology Socrates says the play turned people against him years before his trial. The story that he stood up so the audience could compare his face with the mask comes from a later writer ✦.'),
 o:[opt(X('หันไปดูหน้าโสกราตีสตัวจริง','Turn to look at the real Socrates'),S=>{meet16(S,'socrates');meet16(S,'aristophanes');fx({b:3,kn:1});return X('หน้ากากเหมือนมาก จนคุณหัวเราะออกมาดังกว่าทุกคน โสกราตีสหัวเราะด้วย','The mask is such a good likeness that you laugh louder than anyone. Socrates laughs too.')}),
    opt(X('ไม่หัวเราะ คิดว่ามันใจร้าย','Do not laugh: it seems cruel'),S=>{meet16(S,'aristophanes');fx({kn:2});return X('ข้างๆ คุณ ชายหนุ่มชื่อเพลโตก็ไม่หัวเราะเหมือนกัน','Beside you, a young man named Plato is not laughing either.')})]}),
G16({id:'g16_herms',a:[14,85],cond:S=>S.rg==='ath'&&yr16(2441,2439)(S),t:X('คืนที่หน้าเทพถูกทุบ','The night of the broken gods'),
 x:X('เช้านี้ ทั้งเมืองตื่นมาพบว่าเสาหินรูปเทพเฮอร์มีสหน้าบ้านทุกหลังถูกทุบหน้าเละ ในวันที่กองเรือใหญ่ที่สุดของเอเธนส์กำลังจะออกไปบุกซิซิลี คนลือกันว่าเป็นฝีมือพวกหนุ่มรวยของอัลซิบิอาดีส','This morning the city wakes to find the stone pillars of the god Hermes outside every house smashed in the face, just as Athens’ greatest fleet is about to sail against Sicily. Rumour blames the rich young men around Alcibiades.'),
 n:X('การทุบรูปเฮอร์มีสในปี 415 ปีก่อนคริสตกาลยังเป็นปริศนา อัลซิบิอาดีส หนึ่งในแม่ทัพของการบุกซิซิลี ถูกเรียกตัวกลับมาขึ้นศาล แต่หนีไปเข้ากับสปาร์ตา การบุกซิซิลีจบลงด้วยหายนะในปี 413 ทหารหลายพันคนตายหรือถูกขายเป็นทาสในเหมืองหินที่ซีราคิวส์','The smashing of the herms in 415 BCE remains a mystery. Alcibiades, one of the generals of the Sicilian expedition, was recalled to stand trial but fled to Sparta. The expedition ended in disaster in 413: thousands died or were sold as slaves in the stone quarries of Syracuse.'),
 o:[opt(X('ช่วยซ่อมเสาหน้าบ้าน','Help mend the pillar by your door'),S=>{meet16(S,'alcibiades');fx({b:2,cr:1});return X('จมูกใหม่ของเทพเฮอร์มีสเบี้ยวนิดหน่อย แต่เขาคงไม่ถือ','Hermes’ new nose is a little crooked, but he will probably not mind.')}),
    opt(X('ไปดูกองเรือออกเดินทาง','Go to watch the fleet sail'),S=>{meet16(S,'alcibiades');fx({so:2});return X('อัลซิบิอาดีสยืนบนเรือ หล่อและมั่นใจ คุณไม่รู้ว่านั่นเป็นครั้งสุดท้ายที่เขาจะได้เห็นเอเธนส์ไปอีกหลายปี','Alcibiades stands on deck, handsome and sure of himself. You do not know it is the last he will see of Athens for years.')})]}),
G16({id:'g16_gorgias',a:[14,80],cond:S=>S.rg==='syr'&&yr16(2460,2440)(S),t:X('ครูสอนพูดจากเลออนตินี','The orator from Leontini'),
 x:X('กอร์เกียส ครูสอนการพูดจากเมืองข้างเคียง พิสูจน์ต่อหน้าฝูงชนว่าเฮเลนแห่งทรอยไม่มีความผิด แล้วพิสูจน์ต่อว่าไม่มีอะไรมีอยู่จริง และถ้ามีก็รู้ไม่ได้ คนตบมือ แต่ไม่แน่ใจว่าตบมือให้อะไร','Gorgias, a teacher of speaking from a nearby city, proves before a crowd that Helen of Troy was innocent, then proves that nothing exists, and that if anything did, it could not be known. People applaud, unsure what they are applauding.'),
 n:X('กอร์เกียสจากเลออนตินีในซิซิลี เป็นโซฟิสต์ที่มีชื่อเสียงที่สุดคนหนึ่ง ในปี 427 ปีก่อนคริสตกาล เขาไปเป็นทูตที่เอเธนส์ และทำให้ชาวเอเธนส์ตื่นตะลึงด้วยวิธีพูดของเขา “คำสรรเสริญเฮเลน” ของเขายังเหลืออยู่ เพลโตตั้งชื่อบทสนทนาเล่มหนึ่งตามชื่อเขา','Gorgias of Leontini in Sicily was one of the most famous sophists. In 427 BCE he went as an envoy to Athens and dazzled the Athenians with his speaking. His Encomium of Helen survives, and Plato named a dialogue after him.'),
 o:[opt(X('จ่ายเงินเรียน','Pay for lessons'),S=>{meet16(S,'gorgias');S.ag=Math.max(0,S.ag-2);fx({so:4});return X('คุณพูดเก่งขึ้นมาก จนชนะการเถียงกับแม่เป็นครั้งแรก แต่แค่ครั้งเดียว','You become a far better speaker and win an argument with your mother for the first time. Just once.')}),
    opt(X('ถามว่าถ้าไม่มีอะไรมีอยู่ เงินค่าเรียนมีอยู่ไหม','Ask whether, if nothing exists, his fees do'),S=>{meet16(S,'gorgias');fx({kn:3,b:2});return X('ฝูงชนหัวเราะ กอร์เกียสยิ้มและบอกว่านั่นเป็นคำถามที่ดี ราคาสองเท่า','The crowd laughs. Gorgias smiles and says that is an excellent question, at double the price.')})]}),
G16({id:'g16_platosold',a:[14,85],cond:S=>S.rg==='syr'&&yr16(2413,2411)(S),t:X('นักปรัชญาถูกขาย','A philosopher for sale'),
 x:X('นักปรัชญาจากเอเธนส์ชื่อเพลโตมาสอนทรราชไดโอนีซิอัสแห่งซีราคิวส์ว่าผู้ปกครองที่ดีต้องเป็นนักปรัชญา ไดโอนีซิอัสไม่พอใจเลย ข่าวลือว่าเขาสั่งให้จับเพลโตไปขายเป็นทาส','A philosopher from Athens named Plato has come to teach Dionysius, tyrant of Syracuse, that a good ruler must be a philosopher. Dionysius is not pleased at all. Rumour says he has had Plato sold as a slave.'),
 n:X('ไดโอจีนีส แลเออร์ทิอัสเล่าว่าเพลโตถูกขายเป็นทาสหลังทะเลาะกับไดโอนีซิอัสที่ 1 และเพื่อนต้องไถ่ตัวเขากลับมา ✦ เพลโตกลับไปซีราคิวส์อีกสองครั้งเพื่อพยายามสร้าง “ราชาปราชญ์” และล้มเหลวทุกครั้ง','Diogenes Laertius says Plato was sold into slavery after quarrelling with Dionysius I, and a friend had to ransom him ✦. Plato went back to Syracuse twice more to try to create a “philosopher-king”, and failed every time.'),
 o:[opt(X('ไปดูที่ตลาดค้าทาส','Go to the slave market to see'),S=>{meet16(S,'plato');fx({kn:2,b:-1});return X('ชายร่างใหญ่ยืนนิ่งบนแท่น ไม่ร้องขอใคร คนซื้อถามว่าเขาทำอะไรเป็น เขาตอบว่า “ปกครองคน”','A broad-shouldered man stands still on the block, begging no one. A buyer asks what he can do. He says, “Govern men.”')}),
    opt(X('เงียบไว้ อย่ายุ่งกับทรราช','Keep quiet; do not cross the tyrant'),S=>{meet16(S,'plato');fx({f:1});return X('ในซีราคิวส์ คนเรียนรู้ที่จะกระซิบ','In Syracuse people have learned to whisper.')})]}),
G16({id:'g16_demosthenes',a:[12,85],cond:S=>S.rg==='ath'&&yr16(2378,2350)(S),t:X('ก้อนกรวดในปาก','Pebbles in the mouth'),
 x:X('ที่ชายหาด ชายหนุ่มผอมๆ คนหนึ่งอมก้อนกรวดไว้เต็มปาก แล้วตะโกนแข่งกับเสียงคลื่น คนบอกว่าเขาชื่อดีมอสธีนีส เคยพูดติดอ่างจนคนในสภาหัวเราะเยาะ','On the beach a skinny young man fills his mouth with pebbles and shouts against the roar of the waves. People say his name is Demosthenes, and that the assembly once laughed at his stammer.'),
 n:X('พลูทาร์กเล่าว่าดีมอสธีนีสฝึกพูดโดยอมก้อนกรวดและพูดแข่งกับเสียงคลื่น ✦ เขากลายเป็นนักพูดที่ดีที่สุดของเอเธนส์ และใช้ชีวิตเตือนชาวเอเธนส์ให้สู้กับพระเจ้าฟิลิปแห่งมาซิโดเนีย สุนทรพจน์ของเขาทำให้เกิดคำว่า “philippic” ซึ่งแปลว่าคำพูดโจมตีอย่างรุนแรง','Plutarch says Demosthenes trained by speaking with pebbles in his mouth over the noise of the waves ✦. He became Athens’ greatest orator and spent his life urging the Athenians to resist Philip of Macedon. His speeches gave us the word philippic, a fierce verbal attack.'),
 o:[opt(X('ลองอมกรวดพูดบ้าง','Try speaking with pebbles yourself'),S=>{meet16(S,'demosthenes');fx({so:3,h:-1});return X('คุณเกือบกลืนก้อนหนึ่ง ดีมอสธีนีสพูดไม่ชัดว่า “ระวังด้วย”','You nearly swallow one. Demosthenes mumbles, “Careful.”')}),
    opt(X('ฟังเขาซ้อมพูดเรื่องฟิลิป','Listen to him rehearse against Philip'),S=>{meet16(S,'demosthenes');fx({kn:3,p:1});return X('เสียงของเขาดังกว่าคลื่นในที่สุด คุณรู้สึกอยากไปรบทันที','In the end his voice is louder than the waves, and you want to go to war at once.')})]}),
G16({id:'g16_aristles',a:[10,85],cond:S=>S.rg==='les'&&yr16(2373,2368)(S),t:X('ชายที่นับปลา','The man who counts fish'),
 x:X('ที่ทะเลสาบน้ำเค็มริมเกาะเลสบอส ชายต่างถิ่นชื่ออริสโตเติลกับเพื่อนชื่อธีโอฟราสตัสลุยน้ำทั้งวัน จดว่าปลาหมึกวางไข่ที่ไหน หอยเม่นกินอะไร และถามชาวประมงทุกคนที่ผ่านมา','At the salt lagoon on Lesbos a foreigner named Aristotle and his friend Theophrastus wade about all day, writing down where octopuses lay their eggs and what sea urchins eat, and questioning every fisherman who passes.'),
 n:X('อริสโตเติลอยู่บนเกาะเลสบอสราว 345–344 ปีก่อนคริสตกาล และข้อมูลเรื่องสัตว์ทะเลจำนวนมากในหนังสือของเขามาจากทะเลสาบปีร์ราที่นี่ นักชีววิทยายุคใหม่บางคนจึงเรียกเลสบอสว่าบ้านเกิดของชีววิทยา ธีโอฟราสตัสต่อมาเขียนตำราพืชเล่มแรกๆ ของโลก','Aristotle lived on Lesbos around 345–344 BCE, and much of the sea life in his books comes from the lagoon of Pyrrha there. Some modern biologists call Lesbos the birthplace of biology. Theophrastus later wrote one of the world’s first books on plants.'),
 o:[opt(X('พาเขาไปดูที่ปลาวางไข่','Show him where the fish spawn'),S=>{meet16(S,'aristotle');fx({kn:4,so:1});return X('เขาจดทุกคำที่คุณพูด และถามคำถามที่ชาวประมงทั้งหมู่บ้านไม่เคยคิดจะถาม','He writes down every word you say and asks questions no fisherman in the village ever thought of.')}),
    opt(X('ขายปลาหมึกให้เขา','Sell him an octopus'),S=>{meet16(S,'aristotle');S.ag+=1;fx({b:2});return X('เขาไม่กิน แต่ผ่ามันบนโต๊ะ คุณเสียดาย','He does not eat it but cuts it open on a table. What a waste, you think.')})]}),
G16({id:'g16_hipparchia',a:[14,85],cond:S=>S.rg==='ath'&&yr16(2340,2310)(S),t:X('นักปรัชญาหญิง','The woman philosopher'),
 x:X('หญิงจากตระกูลรวยชื่อฮิปพาร์เคีย ทิ้งบ้านไปใช้ชีวิตแบบไดโอจีนีสกับสามีชื่อเครทีส นอนข้างถนนและเถียงกับนักปรัชญาผู้ชายในงานเลี้ยง ชายคนหนึ่งเยาะว่าเธอควรกลับไปทอผ้า เธอตอบว่าเวลาที่ไม่ได้ทอผ้า เธอใช้เรียนหนังสือ แล้วนั่นผิดตรงไหน','A woman of a rich family named Hipparchia has left home to live like Diogenes with her husband Crates, sleeping in the street and arguing with male philosophers at dinners. A man sneers that she should go back to her loom. She answers that the time she did not spend weaving, she spent on learning: what is wrong with that?'),
 n:X('ไดโอจีนีส แลเออร์ทิอัสเล่าเรื่องฮิปพาร์เคียและคำตอบของเธอ เธอเป็นหนึ่งในนักปรัชญาหญิงไม่กี่คนในกรีกที่เรารู้ชื่อ ร่วมกับลูกศิษย์หญิงของเพลโตและเอพิคิวรัส','Diogenes Laertius records Hipparchia and her reply. She is one of the few Greek women philosophers whose names we know, along with women who studied with Plato and Epicurus.'),
 o:[opt(X('ตบมือให้เธอ','Applaud her'),S=>{meet16(S,'hipparchia');fx({b:3,so:1});return X('ผู้ชายในงานบางคนมองคุณแรงๆ แต่เธอยิ้มให้คุณ','Some of the men glare at you, but she smiles at you.')}),
    opt(X('ถามว่าเธอไม่กลัวคนนินทาหรือ','Ask whether she fears the gossip'),S=>{meet16(S,'hipparchia');fx({kn:3});return X('เธอหัวเราะ “ถ้ากลัวคนนินทา ข้าคงยังนั่งทอผ้าอยู่”','She laughs: “If I feared gossip, I would still be at my loom.”')})]}),
G16({id:'g16_zeno',a:[14,85],cond:S=>S.rg==='ath'&&yr16(2324,2264)(S),t:X('ระเบียงภาพเขียน','The Painted Porch'),
 x:X('ใต้ระเบียงที่มีภาพเขียนในตลาด พ่อค้าที่เรือแตกจากไซปรัสชื่อซีโน สอนว่าเราควบคุมสิ่งที่เกิดขึ้นกับเราไม่ได้ แต่ควบคุมใจตัวเองได้ คนจนและคนรวยนั่งฟังข้างกัน','Under the painted colonnade in the market, a shipwrecked merchant from Cyprus named Zeno teaches that we cannot control what happens to us, only our own minds. Poor and rich sit side by side to listen.'),
 n:X('ซีโนเริ่มสอนที่ “สโตอาโปอิคิเล” ระเบียงภาพเขียนในอะกอราของเอเธนส์ ราว 300 ปีก่อนคริสตกาล ลูกศิษย์จึงถูกเรียกว่าพวกสโตอิก ซึ่งกลายเป็นคำว่า stoic ในภาษาอังกฤษ แปลว่าใจนิ่งเมื่อเจอเรื่องยาก ต่อมาจักรพรรดิโรมันมาร์คัส ออเรลิอัสก็เป็นนักปรัชญาสำนักนี้','Zeno began teaching at the Stoa Poikile, the Painted Porch in the Athenian agora, around 300 BCE, so his followers were called Stoics: our word stoic, calm in hardship. Centuries later the Roman emperor Marcus Aurelius belonged to this school.'),
 o:[opt(X('นั่งฟังทุกวัน','Sit and listen every day'),S=>{meet16(S,'zeno');fx({kn:3,b:3});return X('ปีต่อมาเมื่อไร่ของคุณถูกน้ำท่วม คุณโกรธน้อยกว่าที่คิด','The next year, when your field floods, you are less angry than you expected.')}),
    opt(X('ถามว่าแล้วเรือของเขาที่แตกล่ะ','Ask about his shipwreck'),S=>{meet16(S,'zeno');fx({b:2});return X('เขาบอกว่าเรือแตกคือโชคดีที่สุดในชีวิต เพราะพาเขามาที่นี่','He says the shipwreck was the luckiest thing in his life, because it brought him here.')})]}),
G16({id:'g16_procession',a:[5,85],cond:S=>S.rg==='ale'&&yr16(2304,2296)(S),t:X('ขบวนแห่ของกษัตริย์','The king’s procession'),
 x:X('ขบวนแห่ของกษัตริย์ปโตเลมีเดินผ่านเมืองทั้งวัน มีรถแห่ที่ลากด้วยช้าง สิงโต เสือดาว นกแก้ว และหมีสีขาวตัวใหญ่ ถังเหล้าองุ่นยักษ์ไหลลงถนน และทหารหลายหมื่นคนเดินตาม','King Ptolemy’s procession passes through the city all day: carriages drawn by elephants, lions, leopards, parrots, a great white bear, a giant wine vat spilling into the street, and tens of thousands of soldiers marching behind.'),
 n:X('ขบวนแห่ใหญ่ของปโตเลมีที่ 2 ในอเล็กซานเดรีย ราวทศวรรษ 270 ปีก่อนคริสตกาล ถูกบันทึกโดยคนที่เห็นจริง และถูกคัดลอกไว้ในหนังสือของเอเธเนียส รายการรวมถึงช้าง สัตว์จากแอฟริกาหลายชนิด และหมีสีขาว ซึ่งนักวิชาการยังเดาไม่ได้ว่ามาจากไหน','The Grand Procession of Ptolemy II in Alexandria, around the 270s BCE, was described by an eyewitness and preserved in a book by Athenaeus. The list includes elephants, many African animals and a white bear, whose origin scholars still puzzle over.'),
 o:[opt(X('ปีนขึ้นหลังคาไปดู','Climb onto a roof to watch'),S=>{meet16(S,'ptolemy');fx({b:5,tr:1});return X('คุณนับช้างได้ยี่สิบสี่ตัวก่อนจะเลิกนับ','You count twenty-four elephants before you give up counting.')}),
    opt(X('ไปรองเหล้าองุ่นจากถังยักษ์','Go and catch wine from the giant vat'),S=>{meet16(S,'ptolemy');fx({b:4,h:-1});return X('เสื้อของคุณม่วงไปทั้งตัว และคุณจำส่วนท้ายของขบวนไม่ได้เลย','Your cloak is purple all over, and you remember nothing of the end of the procession.')})]}),
G16({id:'g16_herophilus',a:[16,80],cond:S=>S.rg==='ale'&&yr16(2305,2270)(S)&&S.kn>=20,t:X('หมอที่ผ่าศพ','The doctor who opens the dead'),
 x:X('หมอชื่อเฮโรฟิลัสผ่าศพคนอย่างเปิดเผย ซึ่งในเมืองกรีกอื่นห้ามทำ เขาชี้ให้คุณดูเส้นเล็กๆ สีขาวที่วิ่งจากสมองไปทั่วร่าง และบอกว่าความคิดอยู่ในสมอง ไม่ใช่ในหัวใจ','A doctor named Herophilus openly dissects human bodies, forbidden in other Greek cities. He shows you thin white cords running from the brain throughout the body, and says that thought lives in the brain, not the heart.'),
 n:X('ในอเล็กซานเดรียยุคต้นราชวงศ์ปโตเลมี เฮโรฟิลัสและเอราซิสตราตัสเป็นหมอกลุ่มแรกที่ผ่าศพมนุษย์อย่างเป็นระบบ เฮโรฟิลัสแยกเส้นประสาทออกจากเส้นเอ็นได้ และยืนยันว่าสมองคือศูนย์กลางของระบบประสาท ขณะที่อริสโตเติลเชื่อว่าความคิดอยู่ในหัวใจ','In early Ptolemaic Alexandria, Herophilus and Erasistratus were the first doctors to dissect human bodies systematically. Herophilus told nerves apart from tendons and showed the brain was the centre of the nervous system, whereas Aristotle had believed thought lived in the heart.'),
 o:[opt(X('ช่วยจดสิ่งที่เห็น','Help record what you see'),S=>{meet16(S,'herophilus');fx({kn:5,b:-1});return X('คุณฝันร้ายไปหลายคืน แต่รู้เรื่องร่างกายมนุษย์มากกว่าหมอเกือบทุกคนในโลก','You have nightmares for many nights, but know more about the human body than almost any doctor in the world.')}),
    opt(X('ออกจากห้องไปอาเจียน','Leave the room to be sick'),S=>{meet16(S,'herophilus');fx({b:-1});return X('เขาไม่ว่าอะไร บอกแค่ว่าลูกศิษย์คนแรกของเขาก็เป็นแบบนี้','He does not mind, only says his first pupil did the same.')})]}),
G16({id:'g16_pyrrhus',a:[12,85],cond:S=>S.rg==='syr'&&yr16(2303,2300)(S),t:X('ชัยชนะที่แพง','A costly victory'),
 x:X('กษัตริย์ไพร์รัสแห่งอีไพรัสมาพร้อมช้างศึก เพื่อช่วยซีราคิวส์สู้กับคาร์เธจ ทหารของเขาเล่าว่าเพิ่งชนะโรมันในอิตาลี แต่เสียคนไปมากจนไพร์รัสบ่นว่า “ชนะแบบนี้อีกครั้ง เราจบแน่”','King Pyrrhus of Epirus arrives with war elephants to help Syracuse fight Carthage. His soldiers say he has just beaten the Romans in Italy, but lost so many men that Pyrrhus grumbled, “One more victory like that and we are finished.”'),
 n:X('พลูทาร์กเล่าคำพูดนี้ของไพร์รัสหลังการรบกับโรมในปี 279 ปีก่อนคริสตกาล ✦ และกลายเป็นคำว่า “Pyrrhic victory” หรือชัยชนะที่ต้องจ่ายแพงจนเหมือนแพ้ ไพร์รัสรบในซิซิลีในปี 278–276 ปีก่อนคริสตกาล ก่อนจะกลับไปอิตาลีและแพ้โรม','Plutarch reports Pyrrhus’ words after his battle with Rome in 279 BCE ✦, which gave us the phrase “Pyrrhic victory”: a win so costly it amounts to a loss. Pyrrhus campaigned in Sicily in 278–276 BCE before returning to Italy and losing to Rome.'),
 o:[opt(X('ไปดูช้างศึก','Go and see the elephants'),S=>{meet16(S,'pyrrhus');fx({b:3,kn:1});return X('ช้างตัวหนึ่งดึงเสื้อคุณด้วยงวง ทหารบอกว่ามันชอบคุณ คุณไม่แน่ใจ','An elephant tugs your cloak with its trunk. The soldiers say it likes you. You are not so sure.')}),
    opt(X('ถามว่าทำไมยังรบต่อถ้าชนะแล้วแพ้','Ask why he keeps fighting if winning means losing'),S=>{meet16(S,'pyrrhus');fx({kn:3});return X('ทหารแก่หัวเราะ “เพราะเขาเป็นกษัตริย์ กษัตริย์ไม่เคยรู้จักคำว่าพอ”','An old soldier laughs: “Because he is a king, and kings never know when to stop.”')})]}),
G16({id:'g16_cleomenes',a:[16,85],cond:S=>S.rg==='spa'&&yr16(2268,2266)(S),t:X('เผาสัญญาหนี้','Burning the debts'),
 x:X('กษัตริย์หนุ่มชื่ออากิสสั่งให้นำสัญญาหนี้ทั้งหมดในสปาร์ตามากองกลางตลาดแล้วเผา เขาสัญญาว่าต่อไปจะแบ่งที่ดินใหม่ให้ทุกคนเท่ากัน เหมือนสมัยโบราณ','A young king named Agis orders every debt contract in Sparta piled in the market and burned. Next, he promises, the land will be shared out equally again, as in the old days.'),
 n:X('ในยุคเฮลเลนิสติก ที่ดินสปาร์ตาตกไปอยู่ในมือคนไม่กี่ตระกูล และพลเมืองเหลือไม่ถึงพันคน อากิสที่ 4 เผาสัญญาหนี้ราว 242 ปีก่อนคริสตกาล แต่ถูกประหารในปีต่อมาก่อนจะได้แบ่งที่ดิน คลีโอเมนีสที่ 3 ทำต่อจนสำเร็จราว 227 ปีก่อนคริสตกาล แต่แพ้สงครามในปี 222 และการปฏิรูปก็จบลง','In the Hellenistic age Sparta’s land fell into the hands of a few families, and fewer than a thousand citizens remained. Agis IV burned the debt records around 242 BCE but was executed the next year, before the land could be shared. Cleomenes III carried the reform through around 227 BCE, but lost a war in 222 and it collapsed.'),
 o:[opt(X('โยนสัญญาลงกองไฟ','Throw a contract on the fire'),S=>{meet16(S,'cleomenes');if(S.debt){S.debt=0;S.debtY=0}fx({b:6,p:2});return X('กระดาษไหม้เร็วกว่าที่คิด หนี้สามชั่วคนหายไปในควันเดียว','The papyrus burns faster than you expected. Three generations of debt go up in a single puff of smoke.')}),
    opt(X('ดูอย่างสงสัยว่าจะอยู่ได้นานแค่ไหน','Watch, wondering how long it will last'),S=>{meet16(S,'cleomenes');if(S.debt){S.debt=0;S.debtY=0}fx({kn:2});return X('ปีต่อมา คุณได้คำตอบ','The next year you have your answer.')})]}),
G16({id:'g16_flamininus',a:[8,85],cond:S=>S.rg==='cor'&&yr16(2222,2220)(S),t:X('อิสรภาพของชาวกรีก','The freedom of the Greeks'),
 x:X('ที่งานกีฬาอิสท์เมียนข้างเมือง แม่ทัพโรมันชื่อฟลามินินัสให้ผู้ประกาศขานว่า เมืองกรีกทั้งหมดเป็นอิสระ ไม่ต้องมีทหารต่างชาติ ไม่ต้องจ่ายบรรณาการ ฝูงชนโห่ร้องดังจนไม่มีใครดูกีฬาต่อ','At the Isthmian Games outside the city, a Roman general named Flamininus has the herald proclaim that all the Greek cities are free: no foreign garrisons, no tribute. The crowd roars so loudly that nobody watches the games any more.'),
 n:X('ฟลามินินัสประกาศ “อิสรภาพของชาวกรีก” ในปี 196 ปีก่อนคริสตกาล หลังโรมชนะมาซิโดเนีย พลูทาร์กเล่าว่าเสียงโห่ร้องดังจนนกที่บินผ่านตกลงมา ✦ ห้าสิบปีต่อมา โรมันกลับมาเผาโครินธ์ ห่างจากสนามนี้ไม่กี่กิโลเมตร','Flamininus proclaimed “the freedom of the Greeks” in 196 BCE, after Rome defeated Macedon. Plutarch says the shout was so loud that birds flying overhead fell from the sky ✦. Fifty years later the Romans came back and burned Corinth, a few kilometres away.'),
 o:[opt(X('โห่ร้องให้โรม','Cheer for Rome'),S=>{meet16(S,'flamininus');fx({b:5});return X('คุณเสียงแหบไปสามวัน และเชื่อว่าโลกเปลี่ยนแล้วจริงๆ','You are hoarse for three days, and believe the world has truly changed.')}),
    opt(X('สงสัยว่าทำไมคนต่างชาติต้องเป็นคนประกาศอิสรภาพให้เรา','Wonder why a foreigner must proclaim our freedom'),S=>{meet16(S,'flamininus');fx({kn:3});return X('ผู้เฒ่าข้างๆ พยักหน้าช้าๆ “ใครให้ได้ ก็เอาคืนได้”','An old man beside you nods slowly: “What can be given can be taken back.”')})]}),
G16({id:'g16_polybius',a:[8,85],cond:S=>S.rg==='vil'&&yr16(2209,2207)(S),t:X('โกศของวีรบุรุษ','The hero’s urn'),
 x:X('ขบวนศพเดินผ่านหมู่บ้าน ชายหนุ่มชื่อโพลีเบียสถือโกศบรรจุเถ้าของฟิโลพีเมน แม่ทัพชาวอาร์คาเดียคนสุดท้ายที่ชาวกรีกยกย่อง โกศคลุมด้วยพวงมาลัยจนแทบมองไม่เห็น','A funeral procession passes through the village. A young man named Polybius carries the urn holding the ashes of Philopoemen, the last Arcadian general the Greeks honoured, so covered with garlands it can barely be seen.'),
 n:X('พลูทาร์กเล่าว่าโพลีเบียสถือโกศของฟิโลพีเมนในปี 183 ปีก่อนคริสตกาล โพลีเบียสจากเมกาโลโปลิสในอาร์คาเดียต่อมาถูกพาไปโรมเป็นตัวประกัน ได้เป็นเพื่อนกับแม่ทัพโรมัน และเห็นการทำลายคาร์เธจด้วยตาตัวเอง หนังสือประวัติศาสตร์ของเขาอธิบายว่าทำไมโรมจึงครองโลกได้','Plutarch says Polybius carried Philopoemen’s urn in 183 BCE. Polybius, from Megalopolis in Arcadia, was later taken to Rome as a hostage, befriended Roman generals and saw Carthage destroyed with his own eyes. His history set out to explain how Rome came to rule the world.'),
 o:[opt(X('เดินตามขบวน','Walk with the procession'),S=>{meet16(S,'polybius');fx({b:2,so:2});return X('โพลีเบียสหันมามองคุณครั้งหนึ่ง ใบหน้าเขาเหมือนคนที่กำลังจำทุกอย่างเพื่อเขียนในภายหลัง','Polybius glances at you once, with the look of a man memorising everything to write down later.')}),
    opt(X('โปรยดอกไม้','Scatter flowers'),S=>{meet16(S,'polybius');fx({b:3});return X('ดอกไม้ของคุณตกลงบนโกศพอดี','Your flowers land right on the urn.')})]})
);
const WIDE16=new Set(['g16_herodotus','g16_socrates','g16_hippo','g16_milo','g16_phidias','g16_diogenes','g16_epicurus','g16_zeno','g16_aristarchus','g16_euclid','g16_erat','g16_eureka','g16_anaximander','g16_aesop','g16_hesiod','g16_archilochus','g16_plato','g16_demosthenes','g16_hipparchia','g16_gorgias','g16_pyth','g16_sappho','g16_periander']);
GUMP16.sort((a,b)=>(WIDE16.has(a.id)?1:0)-(WIDE16.has(b.id)?1:0));
