function gump16(a){if(!S||S.ch!==16)return null;for(const e of GUMP16)if(canDec(e,a))return e;return null}

/* ---------- a saying to live by ---------- */
const MOTTO16=[
 {k:'justice',c:'law',ya:2725,q:X('“ปลาและสัตว์ป่ากินกันเอง เพราะพวกมันไม่มีความยุติธรรม แต่เทพซุสให้ความยุติธรรมแก่มนุษย์”','“Fish and beasts devour one another, for they have no justice; but to mankind Zeus gave justice.”'),w:X('เฮสิโอด กวีชาวนา ราว 700 ปีก่อนคริสตกาล','Hesiod, the farmer-poet, about 700 BCE'),fx:{p:2,so:2}},
 {k:'equal',c:'law',ya:2619,q:X('“ข้าเขียนกฎหมายให้คนต่ำและคนสูงเหมือนกัน ให้ความยุติธรรมตรงไปถึงทุกคน”','“I wrote laws alike for the base and the noble, fitting straight justice to each.”'),w:X('โซลอน ผู้ร่างกฎหมายของเอเธนส์ 594 ปีก่อนคริสตกาล','Solon, lawgiver of Athens, 594 BCE'),fx:{p:3,so:2}},
 {k:'web',c:'law',ya:2619,q:X('“กฎหมายเหมือนใยแมงมุม จับได้แต่ตัวเล็กตัวอ่อน คนรวยและมีอำนาจก็ฉีกขาดผ่านไปได้”','“Laws are like spiders’ webs: they hold the weak and small, but the rich and powerful tear right through.”'),w:X('อนาคาร์ซิส ชาวไซเทีย พูดกับโซลอน ตามที่พลูทาร์กเล่า ✦','Anacharsis the Scythian to Solon, as Plutarch tells it ✦'),fx:{kn:2,so:2}},
 {k:'wall',c:'law',ya:2525,q:X('“ประชาชนต้องสู้เพื่อกฎหมาย เหมือนสู้เพื่อกำแพงเมือง”','“The people must fight for the law as for their city wall.”'),w:X('เฮราคลีตัสแห่งเอเฟซัส ราว 500 ปีก่อนคริสตกาล','Heraclitus of Ephesus, about 500 BCE'),fx:{p:3,sv:1}},
 {k:'unwritten',c:'law',ya:2466,q:X('“มีกฎที่ไม่ได้เขียนไว้และไม่มีวันล้ม ซึ่งสูงกว่าคำสั่งของผู้ปกครองคนใด”','“There are unwritten, unfailing laws, higher than any ruler’s decree.”'),w:X('อันติโกเนในละครของโซโฟคลีส 441 ปีก่อนคริสตกาล','Antigone, in Sophocles’ play, 441 BCE'),fx:{b:2,so:2}},
 {k:'useless',c:'law',ya:2456,q:X('“คนที่ไม่สนใจเรื่องบ้านเมือง เราไม่เรียกว่าคนไม่ยุ่ง แต่เรียกว่าคนไร้ประโยชน์”','“A man who takes no interest in public affairs we call not quiet, but useless.”'),w:X('เพริคลีส ในหนังสือของธิวซิดิดีส 431 ปีก่อนคริสตกาล','Pericles, in Thucydides, 431 BCE'),fx:{p:3,so:2}},
 {k:'reason',c:'law',ya:2355,q:X('“กฎหมายคือเหตุผลที่ปลอดจากความอยาก”','“The law is reason free from desire.”'),w:X('อริสโตเติล ในหนังสือการเมือง','Aristotle, in the Politics'),fx:{kn:2,p:2}},
 {k:'best',c:'gen',ya:2750,q:X('“จงเป็นคนที่ดีที่สุด และอยู่เหนือคนอื่นเสมอ”','“Always be the best, and stand above the rest.”'),w:X('อีเลียดของโฮเมอร์','Homer’s Iliad'),fx:{sv:2,p:2}},
 {k:'measure',c:'gen',ya:2725,q:X('“รู้จักประมาณ ความพอดีดีที่สุดในทุกสิ่ง”','“Observe due measure: moderation is best in all things.”'),w:X('เฮสิโอด ในหนังสือ งานและวัน','Hesiod, Works and Days'),fx:{b:2,f:2}},
 {k:'know',c:'gen',ya:2600,q:X('“จงรู้จักตัวเอง”','“Know thyself.”'),w:X('จารึกที่วิหารเดลฟี','inscribed at the temple of Delphi'),fx:{kn:2,b:2}},
 {k:'excess',c:'gen',ya:2600,q:X('“ไม่มีอะไรที่มากเกินไป”','“Nothing in excess.”'),w:X('จารึกที่วิหารเดลฟี','inscribed at the temple of Delphi'),fx:{b:2,h:2}},
 {k:'happy',c:'gen',ya:2600,q:X('“อย่าเพิ่งเรียกใครว่ามีความสุข จนกว่าเขาจะตาย”','“Call no man happy until he is dead.”'),w:X('โซลอน พูดกับกษัตริย์ครีซัส ตามที่เฮโรโดตัสเล่า ✦','Solon to King Croesus, as Herodotus tells it ✦'),fx:{kn:2}},
 {k:'river',c:'gen',ya:2525,q:X('“ไม่มีใครก้าวลงแม่น้ำสายเดียวกันได้สองครั้ง”','“No one steps into the same river twice.”'),w:X('เฮราคลีตัส ตามที่เพลโตเล่า','Heraclitus, as Plato reports him'),fx:{kn:2,tr:1}},
 {k:'man',c:'gen',ya:2465,q:X('“มนุษย์คือเครื่องวัดทุกสิ่ง”','“Man is the measure of all things.”'),w:X('โปรทาโกรัส นักสอนการพูด','Protagoras, the teacher of rhetoric'),fx:{kn:2,so:1}},
 {k:'unexam',c:'gen',ya:2424,q:X('“ชีวิตที่ไม่ได้ตรวจสอบ ไม่คุ้มค่าที่มนุษย์จะมีอยู่”','“The unexamined life is not worth living for a human being.”'),w:X('โสกราตีส ใน “คำแก้ต่าง” ที่เพลโตเขียน 399 ปีก่อนคริสตกาล','Socrates, in Plato’s Apology, 399 BCE'),fx:{kn:3}},
 {k:'harm',c:'gen',ya:2420,q:X('“ช่วยเหลือ หรืออย่างน้อยก็อย่าทำร้าย”','“Help, or at least do no harm.”'),w:X('ตำราของสำนักฮิปพอคราทีส','the books of the Hippocratic school'),fx:{so:2,b:2}},
 {k:'world',c:'gen',ya:2370,q:X('“ข้าเป็นพลเมืองของโลก”','“I am a citizen of the world.”'),w:X('ไดโอจีนีส ✦','Diogenes ✦'),fx:{tr:2,b:2}},
 {k:'death',c:'gen',ya:2320,q:X('“ความตายไม่ใช่อะไรสำหรับเรา”','“Death is nothing to us.”'),w:X('เอพิคิวรัส','Epicurus'),fx:{b:4}}];
const motto16=S=>MOTTO16.find(m=>m.k===S.motto);
function mottoOpts16(S){if(S._mo)return S._mo;const av=MOTTO16.filter(m=>S.ya<=m.ya);const pool=av.length>=3?av:MOTTO16.slice().sort((a,b)=>b.ya-a.ya).slice(0,4);
  const law=pool.filter(m=>m.c==='law'),gen=pool.filter(m=>m.c==='gen'),out=[];
  if(law.length)out.push(pick(law));if(gen.length)out.push(pick(gen));
  const rest=pool.filter(m=>!out.includes(m));while(out.length<3&&rest.length)out.push(rest.splice((rnd()*rest.length)|0,1)[0]);
  S._mo=out.map(m=>m.k);return S._mo}
const mOpt16=i=>({get l(){const k=S&&S._mo&&S._mo[i];const m=MOTTO16.find(x=>x.k===k)||MOTTO16[0];return X(m.q.th+' — '+m.w.th,m.q.en+' — '+m.w.en)},
  run(S){const m=MOTTO16.find(x=>x.k===S._mo[i]);S.motto=m.k;S._mo=null;fx(m.fx);ms(X('เลือกคำคมประจำตัว','Chose a saying to live by'));return X('คุณสลักคำนี้ไว้ในใจ: '+m.q.th,'You carve these words into your heart: '+m.q.en)}});

/* ---------- chapter 16 decisions ---------- */
const DEC_IN16=[
{id:'c16_sea',deck:'child',w:14,ch:16,a:[4,9],t:X('ทะเลที่ไหลเข้ามา','The sea that poured in'),
 x:X('ปู่ชี้ไปทางทิศตะวันตกที่ดวงอาทิตย์ตก แล้วเล่าว่าที่สุดขอบโลก วีรบุรุษเฮราคลีสผ่าภูเขาออกเป็นสองข้าง น้ำจากมหาสมุทรจึงไหลเข้ามาเป็นทะเลของพวกเรา','Grandfather points west, where the sun sets, and tells how at the end of the world the hero Heracles split a mountain in two, and the water of the Ocean poured in to make our sea.'),
 n:X('ตำนานกรีกเรียกสองฝั่งของช่องแคบยิบรอลตาร์ว่า “เสาของเฮราคลีส” ✦ ความจริงทางธรณีวิทยาน่าทึ่งกว่านั้น ราว 6 ล้านปีก่อน ทางน้ำจากมหาสมุทรแอตแลนติกถูกปิด ทะเลเมดิเตอร์เรเนียนระเหยจนเกือบแห้ง เหลือแอ่งเกลือลึกหลายกิโลเมตร ราว 5.3 ล้านปีก่อน น้ำทะเลทะลักกลับเข้ามาทางช่องแคบ แบบจำลองหนึ่งเสนอว่าน้ำส่วนใหญ่ไหลเข้ามาภายในไม่ถึงสองปี มากกว่าแม่น้ำแอมะซอนหลายร้อยเท่า ระดับน้ำสูงขึ้นได้ถึงราววันละ 10 เมตร นักธรณีวิทยายังถกเถียงกันว่าเร็วจริงแค่ไหน','Greek legend called the two sides of the Strait of Gibraltar the Pillars of Heracles ✦. The geology is more astonishing. About 6 million years ago the channels to the Atlantic closed and the Mediterranean evaporated almost dry, leaving salt basins kilometres deep. About 5.3 million years ago the ocean burst back in through the strait. One model suggests most of the water arrived in less than two years, hundreds of times the flow of the Amazon, with the sea rising by up to about 10 metres a day. Geologists still debate how fast it really was.'),
 o:[opt(X('ถามว่าก่อนนั้นมีอะไรอยู่ตรงนี้','Ask what was here before'),S=>{fx({kn:3});return X('ปู่หัวเราะแล้วบอกว่าคงมีแต่หินกับเกลือ คุณไม่รู้ว่าปู่พูดถูกแค่ไหน','Grandfather laughs and says only rocks and salt, probably. You have no idea how right he is.')}),
    opt(X('ถามว่าเดินไปถึงเสาได้ไหม','Ask whether you could walk to the pillars'),S=>{fx({tr:3,b:2});return X('ปู่บอกว่าต้องล่องเรือหลายสิบวัน และหลังเสามีแต่มหาสมุทรที่ไม่มีใครกลับมาเล่า','Grandfather says it is many days by ship, and beyond the pillars is only Ocean, from which no one comes back to tell.')})]},
{id:'c16_frogs',deck:'child',w:9,ch:16,a:[7,13],t:X('กบรอบสระน้ำ','Frogs round a pond'),
 x:X('คุณปีนขึ้นยอดเขาหลังบ้าน มองไปทางไหนก็เห็นทะเล เกาะ และภูเขา ทุกอ่าวมีเมืองเล็กๆ ของตัวเอง ที่มีกษัตริย์ เทพ และกฎหมายของตัวเอง และทุกเมืองคิดว่าตัวเองสำคัญที่สุด','You climb the hill behind the house. Whichever way you look you see sea, islands and mountains. Every bay has its own little town, with its own rulers, gods and laws, and every town thinks it matters most.'),
 n:X('ทะเลกินเข้ามาในแผ่นดินกรีซทุกทิศ และภูเขาแบ่งแผ่นดินเป็นหุบเขาเล็กๆ ไม่มีที่ราบใหญ่ให้กษัตริย์องค์เดียวปกครองได้ง่าย คนกรีกจึงอยู่กันเป็น “โพลิส” หรือนครรัฐเล็กๆ นักประวัติศาสตร์นับได้กว่าหนึ่งพันนครรัฐ เพลโตเขียนว่าชาวกรีกอยู่รอบทะเล “เหมือนมดหรือกบรอบสระน้ำ” แม้จะแยกกัน พวกเขาก็พูดภาษาเดียวกัน ไหว้เทพองค์เดียวกัน และไปแข่งที่โอลิมเปียด้วยกัน','The sea reaches into Greece from every side, and mountains split the land into small valleys, with no great plain one king could easily rule. So Greeks lived in poleis, small city-states: historians count more than a thousand. Plato wrote that the Greeks lived round the sea “like ants or frogs round a pond”. Divided as they were, they spoke one language, worshipped the same gods and competed together at Olympia.'),
 o:[opt(X('นับเมืองที่มองเห็น','Count the towns you can see'),S=>{fx({kn:2,tr:2});return X('คุณนับได้เจ็ดเมือง และรู้ว่าสามเมืองในนั้นเป็นศัตรูกับเมืองของคุณ','You count seven, and know that three of them are enemies of yours.')}),
    opt(X('ร้องเพลงให้กบฟัง','Sing to the frogs'),S=>{fx({b:3});return X('กบในบ่อร้องตอบ คุณคิดว่ามันคงคิดว่าบ่อของมันคือโลกทั้งใบ เหมือนกัน','The frogs in the pool croak back. You think they probably believe their pond is the whole world too.')})]},
{id:'c16_homer',deck:'child',w:6,ch:16,a:[5,13],t:X('ความโกรธของอะคิลลีส','The anger of Achilles'),
 x:X('ในงานเลี้ยง นักขับลำนำตาบอดท่องเรื่องสงครามกรุงทรอยติดต่อกันทั้งคืนโดยไม่เปิดดูอะไรเลย คุณง่วงแต่ไม่ยอมหลับ เพราะอยากรู้ว่าเฮกเตอร์จะรอดไหม','At a feast a blind bard recites the war at Troy all night long without looking at anything. You are sleepy but refuse to sleep, because you want to know whether Hector survives.'),
 n:X('อีเลียดและโอดิสซีย์น่าจะถูกแต่งในศตวรรษที่ 8–7 ก่อนคริสตกาล จากบทกวีที่ท่องจำต่อกันมาหลายร้อยปีก่อนจะถูกเขียนลง นักวิชาการยังเถียงกันว่า “โฮเมอร์” เป็นคนคนเดียวหรือหลายคน เด็กกรีกเรียนอ่านจากบทกวีของเขา และบางคนท่องได้ทั้งเรื่อง ภาพว่าโฮเมอร์ตาบอดเป็นตำนาน ✦','The Iliad and the Odyssey were probably composed in the 8th or 7th century BCE, from poems memorised and passed on for centuries before being written down. Scholars still argue whether “Homer” was one poet or many. Greek children learned to read from his verses, and some could recite them entire. The blind Homer is a legend ✦.'),
 o:[opt(X('ท่องตาม','Recite along'),S=>{fx({kn:3,so:1});return X('คุณจำได้สามสิบบรรทัด ผู้ใหญ่ตบมือให้','You remember thirty lines, and the grown-ups applaud.')}),
    opt(X('ถามว่าทำไมเทพเจ้าทะเลาะกันเหมือนคน','Ask why the gods quarrel like people'),S=>{fx({kn:2,b:2});return X('นักขับลำนำหัวเราะแล้วตอบว่า “ก็เพราะเราเป็นคนเล่า”','The bard laughs: “Because people are the ones telling it.”')})]},
{id:'c16_ped',deck:'child',w:6,ch:16,a:[7,13],cond:S=>!!S.schOK,t:X('ทาสผู้พาไปโรงเรียน','The boy-leader'),
 x:X('ทุกเช้า ทาสแก่ของครอบครัวเดินตามคุณไปโรงเรียน ถือพิณและแผ่นขี้ผึ้งให้ และตีคุณเบาๆ ด้วยไม้ถ้าคุณมัวเล่น ครูสอนอ่านเขียน ครูอีกคนสอนพิณ และอีกคนสอนมวยปล้ำ','Every morning the family’s old slave walks you to school, carrying your lyre and wax tablet, and taps you with a stick if you dawdle. One teacher teaches letters, another the lyre, another wrestling.'),
 n:X('ทาสที่พาเด็กไปโรงเรียนเรียกว่า “ไพดาโกกอส” ซึ่งกลายเป็นคำว่า pedagogue (ครู) ในภาษาอังกฤษ โรงเรียนไม่ฟรี ลูกคนจนส่วนใหญ่ได้เรียนแค่ไม่กี่ปีหรือไม่ได้เรียนเลย เด็กผู้หญิงส่วนใหญ่เรียนที่บ้าน','The slave who took a boy to school was the paidagogos, which became the English word pedagogue. Schools charged fees: most poor boys got only a few years or none, and most girls learned at home.'),
 o:[opt(X('ชวนทาสแก่คุยระหว่างทาง','Talk with the old slave on the way'),S=>{fx({so:2,kn:2});return X('เขาเคยเป็นลูกชาวนาในทราเซีย ก่อนถูกจับมาขาย เขาเล่าเรื่องบ้านเกิดได้ดีกว่าครูเล่าเรื่องโฮเมอร์','He was a farmer’s son in Thrace before he was captured and sold. He tells of his homeland better than the teacher tells Homer.')}),
    opt(X('วิ่งหนีไปเล่นที่ท่าเรือ','Run off to play at the harbour'),S=>{fx({b:3,kn:-1});return X('ทาสแก่หอบตามมาจนทัน แล้วถูกพ่อของคุณดุแทนคุณ','The old slave puffs after you and catches up, and then your father scolds him instead of you.')})]},
{id:'c16_agoge',deck:'child',w:12,ch:16,a:[7,7],cond:S=>S.rg==='spa'&&S.cls==='elite'&&S.sex==='m',t:X('อายุเจ็ดขวบ','Seven years old'),
 x:X('วันเกิดอายุเจ็ดขวบ คุณถูกพาออกจากบ้านไปอยู่กับเด็กผู้ชายรุ่นเดียวกัน ได้เสื้อตัวเดียวทั้งปี เดินเท้าเปล่า นอนบนกกที่ถอนเองจากริมแม่น้ำ และได้อาหารน้อยจนต้องขโมย','On your seventh birthday you are taken from home to live with the other boys your age. You get one cloak for the whole year, go barefoot, sleep on reeds you pull from the river yourself, and are fed so little that you must steal.'),
 n:X('ระบบฝึกเด็กชายของสปาร์ตาเรียกว่า “อโกเก” เด็กถูกสอนให้ขโมยอาหารโดยไม่ถูกจับ ถ้าถูกจับจะถูกเฆี่ยน ไม่ใช่เพราะขโมย แต่เพราะซุ่มซ่าม เรื่องเด็กที่ซ่อนลูกจิ้งจอกใต้เสื้อจนมันกัดท้องตายโดยไม่ร้องสักคำ มาจากพลูทาร์ก ✦','The Spartan training system was the agoge. Boys were taught to steal food without being caught; if caught they were whipped, not for stealing but for clumsiness. The tale of the boy who hid a fox cub under his cloak and let it bite him to death without a sound comes from Plutarch ✦.'),
 o:[opt(X('ขโมยชีสจากแท่นบูชา','Steal cheese from the altar'),S=>{if(rnd()<.4){fx({h:-6,b:-3});return X('คุณถูกจับและถูกเฆี่ยน เด็กคนอื่นมองด้วยความดูถูก ไม่ใช่สงสาร','You are caught and whipped. The other boys look on with contempt, not pity.')}fx({sv:4,p:2});return X('ไม่มีใครเห็น คืนนั้นคุณแบ่งชีสให้เพื่อนในกลุ่ม','No one sees. That night you share the cheese with your group.')}),
    opt(X('อดทนหิวไว้','Endure the hunger'),S=>{fx({sv:3,h:-3});return X('คุณผอมจนเห็นซี่โครง แต่ครูฝึกพยักหน้าให้','You grow thin enough to count your ribs, but the trainer gives you a nod.')})]},
{id:'y16_motto',deck:'youth',w:16,ch:16,a:[14,20],cond:S=>!S.motto,t:X('คำคมประจำตัว','A saying to live by'),
 xf:S=>{mottoOpts16(S);return X('ที่ลานกลางเมือง ผู้คนชอบยกคำพูดของนักปราชญ์มาเถียงกันทุกเรื่อง ตั้งแต่ราคาน้ำมันมะกอกไปจนถึงสงคราม ครูของคุณบอกว่าคนที่ดีต้องมีคำพูดสักประโยคที่ยึดถือไปตลอดชีวิต คุณเลือกประโยคไหน','In the square people quote the wise to argue about everything, from the price of olive oil to war. Your teacher says a good person should have one saying to hold to all their life. Which do you choose?')},
 n:X('ชาวกรีกรักการรวบรวมคำคม ที่วิหารเดลฟีมีคำสอนสั้นๆ จารึกไว้ให้ทุกคนอ่าน และชาวกรีกยกย่อง “ปราชญ์ทั้งเจ็ด” ที่แต่ละคนมีคำพูดประจำตัว ทั้งเรื่องกฎหมาย การปกครอง และการใช้ชีวิต ทุกวันนี้คำคมกรีกหลายประโยคยังถูกยกมาใช้ในศาล ในโรงเรียนแพทย์ และบนผนังห้องเรียน แต่บางประโยคก็เป็นเรื่องเล่าที่ไม่แน่ว่าใครพูดจริง ✦','Greeks loved collecting sayings. At Delphi short precepts were inscribed for all to read, and Greeks honoured the “Seven Sages”, each with sayings of his own on law, government and how to live. Many Greek sayings are still quoted in law courts, medical schools and on classroom walls, though some are stories whose real speaker is uncertain ✦.'),
 of:S=>{mottoOpts16(S);return [0,1,2].filter(i=>S._mo[i]).map(mOpt16)}},
{id:'y16_marry',deck:'youth',w:5,ch:16,a:[14,30],cond:S=>!S.partner&&S.cls!=='slave'&&(S.sex==='f'||S.age>=24),t:X('สินเดิม','The dowry'),
 xf:S=>S.sex==='f'?X('พ่อของคุณตกลงเรื่องแต่งงานแล้ว เจ้าบ่าวอายุราวสามสิบ คุณเพิ่งเคยเห็นหน้าเขาครั้งเดียว พ่อเตรียมสินเดิมเป็นเงินและผ้าทอที่จะติดตัวคุณไป ถ้าเขาหย่า เขาต้องคืนให้ทั้งหมด','Your father has arranged your marriage. The groom is about thirty; you have seen his face once. Your father sets aside a dowry of silver and woven cloth that goes with you; if he divorces you, he must give it all back.'):X('ครอบครัวของคุณกับครอบครัวเพื่อนบ้านคุยเรื่องแต่งงาน เจ้าสาวอายุสิบสี่ ครอบครัวเธอจะให้สินเดิมเป็นเงินและต้นมะกอกสิบต้น','Your family and a neighbouring family discuss a marriage. The bride is fourteen; her family will give a dowry of silver and ten olive trees.'),
 n:X('ในเอเธนส์ ผู้หญิงมักแต่งงานราวอายุ 14–15 ปี กับผู้ชายอายุราว 30 ปี การแต่งงานจัดโดยพ่อหรือผู้ปกครองชาย ผู้หญิงเป็นเจ้าของที่ดินหรือทำสัญญาซื้อขายใหญ่ๆ เองไม่ได้ สินเดิมเป็นหลักประกันของเธอ ที่สปาร์ตา ผู้หญิงแต่งงานช้ากว่า และถือครองที่ดินได้','In Athens women usually married at about 14–15, to men of about 30. Marriages were arranged by a father or male guardian. Women could not own land or make large contracts themselves; the dowry was their security. In Sparta women married later and could hold land.'),
 o:[opt(X('ตกลง','Agree'),S=>{S.partner=1;ms(X('สร้างครอบครัวใหม่','Founded a new household'));mkP('partner');fx({b:6});return X('ในขบวนแห่เจ้าสาวตอนกลางคืน มีคบไฟ เพลง และเกวียนที่พาเจ้าสาวไปบ้านใหม่','The wedding procession goes by night, with torches, songs and a cart carrying the bride to her new home.')}),
    opt(X('ขอให้รอไปก่อน','Ask to wait'),S=>{fx({b:-1});return X('ผู้ใหญ่บ่น แต่ยอมรอ','The elders grumble, but agree to wait.')})]},
{id:'y16_eph',deck:'youth',w:5,ch:16,a:[17,20],cond:S=>S.sex==='m'&&S.cls!=='slave'&&S.rg!=='spa',t:X('ทหารหนุ่ม','A young soldier'),
 x:X('ถึงวัยที่ต้องฝึกเป็นทหาร คุณต้องเฝ้าป้อมตามชายแดนสองปี และสาบานต่อเทพเจ้าว่าจะไม่ทิ้งเพื่อนข้างกายในแถวรบ','You are old enough for military training: two years guarding the border forts, and an oath to the gods never to desert the man beside you in the line.'),
 n:X('ทหารราบกรีกเรียกว่าโฮพลไลต์ ตามชื่อโล่กลมใหญ่ “ฮอพลอน” แต่ละคนซื้ออาวุธเอง โล่ของแต่ละคนป้องกันครึ่งตัวของตัวเองและครึ่งตัวของคนข้างๆ คนที่ทิ้งโล่หนีจึงถูกดูถูกที่สุด คำสาบานของทหารหนุ่มชาวเอเธนส์ยังเหลือบนจารึกหินจากศตวรรษที่ 4 ก่อนคริสตกาล','Greek infantry were called hoplites, perhaps after the big round shield. Each man bought his own armour. Each shield covered half its bearer and half the man beside him, so throwing away your shield was the worst disgrace. The oath of young Athenian soldiers survives on a 4th-century BCE inscription.'),
 o:[opt(X('สาบานเสียงดัง','Swear in a loud voice'),S=>{fx({sv:3,p:3});return X('เสียงของคุณดังกว่าใคร แล้วคุณก็อายตัวเองทั้งวัน','Your voice is louder than anyone’s, and you are embarrassed all day.')}),
    opt(X('สาบานเบาๆ แต่จำทุกคำ','Swear quietly, but remember every word'),S=>{fx({kn:2,b:2});return X('คุณยังท่องคำสาบานนั้นได้จนแก่','You can still recite that oath when you are old.')})]},
{id:'a16_colony',deck:'adult',w:7,ch:16,a:[17,40],cond:S=>era16(S.ya)==='arch'&&['cor','mil','les','ath'].includes(S.rg)&&S.cls!=='slave',t:X('เรือไปอาณานิคม','The ships to the colony'),
 x:X('ที่ดินไม่พอเลี้ยงทุกคน เมืองของคุณถามเทพที่เดลฟี เทพตอบให้ส่งคนไปตั้งเมืองใหม่ข้ามทะเลทางตะวันตก หัวหน้าการเดินทางกำลังหาคนหนุ่มสาวที่กล้าพอ','There is not enough land for everyone. Your city asked the god at Delphi, and the answer was to send people to found a new city across the sea to the west. The leader is looking for young people bold enough to go.'),
 n:X('ระหว่าง 750–550 ปีก่อนคริสตกาล ชาวกรีกตั้งอาณานิคมหลายร้อยแห่งตั้งแต่สเปนถึงทะเลดำ ตอนใต้ของอิตาลีมีเมืองกรีกมากจนชาวโรมันเรียกว่า “กรีกใหญ่” หลายเมืองยังมีคนอยู่ทุกวันนี้ เช่น มาร์เซย์ เนเปิลส์ และอิสตันบูล อาณานิคมเป็นเมืองอิสระ ไม่ได้อยู่ใต้เมืองแม่','Between about 750 and 550 BCE Greeks founded hundreds of colonies from Spain to the Black Sea. Southern Italy had so many Greek cities that the Romans called it Magna Graecia, “Great Greece”. Many are still inhabited, such as Marseille, Naples and Istanbul. Colonies were independent cities, not ruled by their mother city.'),
 o:[opt(X('ลงเรือไป','Take ship'),S=>{const to=S.ya<=2625&&rnd()<.5?'mas':(S.ya<=2758?'syr':null);if(!to){fx({tr:4,so:2});return X('เรือพาคุณไปตั้งเมืองเล็กๆ บนชายฝั่งที่ไม่มีใครเคยได้ยินชื่อ','The ships carry you to found a little town on a coast no one has heard of.')}moveTo(to);fx({tr:5,b:3,f:-3});return X('คุณข้ามทะเลไปเริ่มชีวิตใหม่ในเมืองที่ยังมีแต่บ้านไม่กี่หลังกับแท่นบูชา','You cross the sea to start again in a town that is still only a few houses and an altar.')}),
    opt(X('อยู่บ้าน','Stay home'),S=>{fx({f:2});return X('เรือออกไปหลายลำ บางลำไม่กลับมาอีก','Many ships sail. Some never come back.')})]},
{id:'a16_ostra',deck:'adult',w:7,ch:16,a:[20,80],cond:S=>S.rg==='ath'&&S.sex==='m'&&['free','elite'].includes(S.cls)&&S.ya<=2512&&S.ya>=2442,t:X('วันเนรเทศ','Ostracism day'),
 x:X('ปีนี้สภาตัดสินให้มีการออกเสียงเนรเทศ ทุกคนถือเศษหม้อมาเขียนชื่อนักการเมืองที่อยากให้ออกจากเมืองสิบปี ใครได้มากที่สุดต้องไป','This year the assembly has voted to hold an ostracism. Everyone brings a potsherd to write the name of the politician they want out of the city for ten years. Whoever gets the most must go.'),
 n:X('การเนรเทศแบบนี้ไม่ใช่การลงโทษคดีอาญา คนที่ถูกเนรเทศไม่เสียทรัพย์สินและกลับมาได้หลังสิบปี มันถูกใช้ราว 487–417 ปีก่อนคริสตกาล ครั้งสุดท้ายเป็นที่รู้กันว่าใช้ผิดจุด เมื่อสองนักการเมืองคู่แข่งร่วมมือกันให้คนที่สามถูกเนรเทศแทน หลังจากนั้นไม่มีใครใช้อีก','Ostracism was not a criminal punishment: the exile kept his property and could return after ten years. It was used from about 487 to 417 BCE. The last time is known to have misfired, when two rival politicians joined forces to have a third man exiled instead; after that it was never used again.'),
 o:[opt(X('เขียนชื่อคนที่มีอำนาจมากที่สุด','Write the most powerful man’s name'),S=>{fx({p:2,so:1});return X('เขาได้แค่ไม่กี่ร้อยเสียง และยังอยู่ในเมืองต่อ','He gets only a few hundred votes and stays.')}),
    opt(X('ไม่ไปลงคะแนน','Do not vote'),S=>{fx({f:1,p:-1});return X('เพื่อนบ้านเรียกคุณว่า “คนไร้ประโยชน์” ครึ่งเล่นครึ่งจริง','Your neighbours call you “useless”, half joking.')})]},
{id:'a16_jury',deck:'adult',w:5,ch:16,a:[30,80],cond:S=>S.rg==='ath'&&S.sex==='m'&&['free','elite'].includes(S.cls)&&S.ya<=2490,t:X('เครื่องจับสลาก','The allotment machine'),
 x:X('เช้านี้คุณหย่อนป้ายชื่อทองแดงลงในช่องของแผ่นหินใหญ่ เจ้าหน้าที่ปล่อยลูกบอลดำและขาวลงในท่อ ลูกขาวหมายถึงแถวของคุณได้เป็นลูกขุนวันนี้ คดีคือเพื่อนบ้านสองคนเถียงกันเรื่องแพะ','This morning you slot your bronze name-ticket into a great stone slab. An official drops black and white balls down a tube: white means your row serves on a jury today. The case: two neighbours quarrelling over a goat.'),
 n:X('ชาวเอเธนส์ใช้เครื่องจับสลากหิน “เคลโรเทริออน” เลือกลูกขุนแบบสุ่ม เพื่อไม่ให้ใครติดสินบนลูกขุนล่วงหน้าได้ ลูกขุนได้ค่าตอบแทนวันละครึ่งดรัคมา ศาลหนึ่งมีลูกขุนหลายร้อยคน ไม่มีผู้พิพากษา และไม่มีทนาย ทุกคนต้องพูดแก้ต่างให้ตัวเอง','Athenians chose jurors at random with a stone allotment machine, the kleroterion, so no one could bribe a jury in advance. Jurors were paid half a drachma a day. A court had hundreds of jurors, no judge and no lawyers: everyone spoke for himself.'),
 o:[opt(X('ตั้งใจฟังทั้งสองฝ่าย','Listen carefully to both sides'),S=>{fx({kn:2,p:2});S.ag+=1;return X('แพะได้กลับไปหาคนที่พูดเก่งน้อยกว่า แต่พูดจริงกว่า','The goat goes back to the one who speaks less well but more truly.')}),
    opt(X('หลับในศาล','Doze off in court'),S=>{fx({b:2});S.ag+=1;return X('คุณตื่นมาทันลงคะแนน และได้ค่าแรงครึ่งดรัคมาเท่ากับคนอื่น','You wake in time to vote and are paid your half-drachma like everyone else.')})]},
{id:'a16_metic',deck:'adult',w:5,ch:16,a:[18,70],cond:S=>S.cls==='dep'&&['ath','cor','syr','ale','mil'].includes(S.rg),t:X('คนต่างถิ่น','The resident foreigner'),
 x:X('คุณเกิดในเมืองนี้ เสียภาษี ไปรบเมื่อถูกเรียก แต่ครอบครัวคุณมาจากเมืองอื่นเมื่อสามชั่วคนก่อน คุณจึงยังเป็น “คนต่างถิ่น” ซื้อบ้านหรือที่ดินไม่ได้ และต้องมีพลเมืองค้ำประกันเวลาขึ้นศาล','You were born in this city, pay taxes and go to war when called, but your family came from elsewhere three generations ago. So you are still a “resident foreigner”: you cannot buy a house or land, and need a citizen sponsor to go to court.'),
 n:X('ในเอเธนส์ คนต่างถิ่นที่อยู่อาศัยเรียกว่า “เมทิก” ต้องจ่ายภาษีหัวปีละ 12 ดรัคมาสำหรับผู้ชาย 6 ดรัคมาสำหรับผู้หญิง หลังกฎหมายปี 451 ปีก่อนคริสตกาล คนที่จะเป็นพลเมืองเอเธนส์ได้ต้องมีทั้งพ่อและแม่เป็นชาวเอเธนส์ นักคิดและนักธุรกิจดังหลายคน รวมทั้งอริสโตเติล เป็นเมทิกตลอดชีวิต','In Athens resident foreigners were called metics. They paid a yearly tax of 12 drachmas for a man and 6 for a woman. After a law of 451 BCE, only those with an Athenian father and mother could be citizens. Many famous thinkers and businessmen, Aristotle among them, were metics all their lives.'),
 o:[opt(X('ทำธุรกิจให้รวยแทน','Get rich in business instead'),S=>{S.ag+=3;fx({so:2,b:-1});return X('เงินซื้อสิทธิ์พลเมืองไม่ได้ แต่ซื้อความเคารพได้บ้าง','Money cannot buy citizenship, but it buys a little respect.')}),
    opt(X('หาพลเมืองเป็นเพื่อนสนิท','Make close friends among the citizens'),S=>{fx({so:4});return X('เพื่อนพาคุณเข้าไปในงานเลี้ยงที่ไม่มีใครถามว่าคุณมาจากไหน','A friend takes you into feasts where no one asks where you are from.')})]},
{id:'a16_free',deck:'adult',w:7,ch:16,a:[20,70],cond:S=>S.cls==='slave'&&S.rg!=='spa',t:X('ซื้ออิสรภาพ','Buying freedom'),
 x:X('คุณเก็บเศษเงินทุกเหรียญที่นายให้เป็นรางวัลมาหลายปี จนเกือบพอซื้อตัวเอง ที่วิหารเดลฟี ทาสสามารถ “ขายตัว” ให้เทพอพอลโล แล้วเทพก็ปล่อยให้เป็นอิสระ','For years you have saved every coin your owner gave you as a reward, until you almost have enough to buy yourself. At Delphi a slave can be “sold” to the god Apollo, who then sets them free.'),
 n:X('บนกำแพงที่เดลฟีมีจารึกการปลดปล่อยทาสกว่าพันรายการ ทาสส่วนใหญ่จ่ายเงินซื้อตัวเอง และหลายคนยังต้องทำงานให้นายเก่าต่อไปจนนายตาย ทาสในเหมืองเงินที่ลอเรียนแทบไม่มีโอกาสแบบนี้ บางคนทำงานในอุโมงค์สูงไม่ถึงเมตร','The walls at Delphi carry more than a thousand inscriptions recording the freeing of slaves. Most slaves paid for their own freedom, and many still had to serve their former owner until the owner died. Slaves in the silver mines at Laurion had almost no such chance; some worked in tunnels less than a metre high.'),
 o:[opt(X('จ่ายเงินทั้งหมดที่มี','Pay everything you have'),S=>{if(S.ag>=4||rnd()<.5){S.ag=0;S.cls='dep';fx({b:12});ms(X('ซื้ออิสรภาพของตัวเอง','Bought your own freedom'));return X('ชื่อของคุณถูกสลักบนกำแพงหิน คุณเป็นอิสระ แต่ยังเป็นคนต่างถิ่นที่ไม่มีสิทธิ์พลเมือง','Your name is carved on the stone wall. You are free, though still a foreigner without citizen rights.')}fx({b:-6});return X('นายขึ้นราคา บอกว่าคุณมีค่ามากกว่านั้น','Your owner raises the price, saying you are worth more than that.')}),
    opt(X('เก็บเงินต่ออีกสองสามปี','Save a few more years'),S=>{S.ag+=1;fx({b:-1});return X('ทุกเหรียญที่ได้ คุณซ่อนไว้ในรอยแตกของผนัง','Every coin you get, you hide in a crack in the wall.')})]},
{id:'a16_thesmo',deck:'adult',w:5,ch:16,a:[16,70],cond:S=>S.sex==='f'&&S.cls!=='slave',t:X('เทศกาลของผู้หญิง','The women’s festival'),
 x:X('สามวันในฤดูใบไม้ร่วง ผู้หญิงที่แต่งงานแล้วทั้งเมืองไปตั้งค่ายบนเนินเขา ทำพิธีให้เทพีดีมิเทอร์ ผู้ชายห้ามเข้าใกล้ ทุกคนกินอาหาร หัวเราะ และพูดเรื่องที่ไม่มีวันพูดต่อหน้าสามี','For three days in autumn the married women of the city camp on a hill and hold rites for the goddess Demeter. Men may not come near. Everyone eats, laughs and says things they would never say in front of their husbands.'),
 n:X('เทศกาลเทสโมโฟเรียเป็นหนึ่งในเทศกาลเดียวที่ผู้หญิงกรีกได้รวมตัวกันเองโดยไม่มีผู้ชาย สิ่งที่เกิดขึ้นในพิธีถูกเก็บเป็นความลับจนเรารู้น้อยมาก นักเขียนบทละครชายคนหนึ่งเขียนตลกเรื่องผู้ชายที่แต่งตัวเป็นผู้หญิงแอบเข้าไป','The Thesmophoria was one of the few festivals where Greek women gathered by themselves, without men. Its rites were kept so secret that we know very little. A male comic playwright wrote a comedy about a man who dresses as a woman to sneak in.'),
 o:[opt(X('ร่วมทุกพิธี','Join every rite'),S=>{fx({b:6,so:3});return X('คุณกลับบ้านมาเสียงแหบ และยิ้มไปทั้งอาทิตย์','You come home hoarse, and smile for a week.')}),
    opt(X('ฟังผู้หญิงสูงอายุเล่าเรื่อง','Listen to the old women’s stories'),S=>{fx({kn:3,so:2});return X('คุณได้รู้เรื่องลับของเมืองมากกว่าที่ผู้ชายในสภารู้ทั้งหมด','You learn more of the city’s secrets than all the men in the assembly know.')})]},
{id:'a16_symp',deck:'adult',w:4,ch:16,a:[18,70],cond:S=>S.sex==='m'&&S.cls!=='slave'&&S.rg!=='vil',t:X('งานเลี้ยงดื่ม','The drinking party'),
 x:X('ในงานเลี้ยงที่ทุกคนนอนเอนบนตั่ง หัวหน้างานสั่งให้ผสมเหล้าองุ่นกับน้ำสามส่วน คนหนึ่งท่องกลอน อีกคนเถียงเรื่องความรัก แล้วทุกคนเล่นเกมสะบัดเหล้าก้นถ้วยใส่เป้า','At a party where everyone reclines on couches, the host orders the wine mixed with three parts water. One man recites verses, another argues about love, then everyone plays the game of flicking the dregs of their cups at a target.'),
 n:X('ชาวกรีกถือว่าการดื่มเหล้าองุ่นไม่ผสมน้ำเป็นนิสัยของคนป่าเถื่อน งานเลี้ยงดื่มเรียกว่า “ซิมโพเซียม” เป็นที่มาของคำว่า symposium ในภาษาอังกฤษ เกมสะบัดเหล้าใส่เป้าเรียกว่า “คอตทาบอส” ผู้หญิงที่มาร่วมงานแบบนี้มักเป็นนักดนตรีหรือหญิงบริการ ไม่ใช่ภรรยาของแขก','Greeks thought drinking unmixed wine was barbarian. The drinking party was the symposion, origin of the English word symposium. The game of flicking wine at a target was kottabos. Women at these parties were usually musicians or paid companions, not the guests’ wives.'),
 o:[opt(X('เล่นคอตทาบอส','Play kottabos'),S=>{fx({b:4,so:2});return X('เหล้าของคุณกระเด็นใส่เสื้อของแขกข้างๆ ทั้งห้องหัวเราะ','Your wine splashes the next guest’s cloak, and the whole room laughs.')}),
    opt(X('ร่วมถกเรื่องความรัก','Join the argument about love'),S=>{fx({kn:2,so:2});return X('คุณพูดได้ดีจนมีคนจดไว้ ตอนเช้าคุณจำไม่ได้ว่าพูดอะไรไป','You speak so well someone writes it down. In the morning you cannot remember what you said.')})]},
{id:'a16_theatre',deck:'adult',w:5,ch:16,a:[10,80],cond:S=>['ath','cor','syr','ale'].includes(S.rg)&&S.ya<=2490,t:X('เทศกาลละคร','The drama festival'),
 x:X('ทั้งเมืองหยุดงานไปโรงละครกลางแจ้ง ตั้งแต่เช้าถึงเย็นมีโศกนาฏกรรมสามเรื่อง และละครตลกที่ล้อนักการเมืองที่นั่งดูอยู่แถวหน้า นักแสดงทุกคนเป็นผู้ชายใส่หน้ากาก แม้ตัวละครเป็นผู้หญิง','The whole city stops work for the open-air theatre: three tragedies from morning to evening, then a comedy mocking the politicians sitting in the front row. Every actor is a man in a mask, even in women’s roles.'),
 n:X('ละครกรีกเกิดในเทศกาลบูชาเทพไดโอนิซัส คำว่า tragedy อาจมาจากคำว่า “เพลงแพะ” โรงละครที่เอพิเดารอสจุคนได้ราว 13,000–14,000 คน และเสียงกระซิบบนเวทียังได้ยินไปถึงแถวหลังสุด ต่อมาเอเธนส์มีกองทุนจ่ายค่าตั๋วให้พลเมืองที่จน','Greek drama grew from festivals for the god Dionysus; the word tragedy may come from “goat song”. The theatre at Epidaurus held about 13,000–14,000 people, and a whisper on stage can still be heard in the back row. Later Athens had a fund that paid poor citizens’ tickets.'),
 o:[opt(X('ร้องไห้กับโศกนาฏกรรม','Weep at the tragedies'),S=>{fx({b:3,kn:2});return X('คุณกลับบ้านตาบวม แต่รู้สึกเบาเหมือนได้ล้างใจ','You go home with swollen eyes, but feeling light, as if washed clean.')}),
    opt(X('หัวเราะกับละครตลก','Laugh at the comedy'),S=>{fx({b:5});return X('นักการเมืองแถวหน้าหน้าแดงก่ำ ทั้งโรงละครหัวเราะจนพื้นหินสั่น','The politicians in the front row turn crimson, and the whole theatre laughs until the stone seats shake.')})]},
{id:'a16_library',deck:'adult',w:6,ch:16,a:[14,80],cond:S=>S.rg==='ale'&&S.ya<=2310,t:X('หนังสือบนเรือ','The books on the ships'),
 x:X('เจ้าหน้าที่ของกษัตริย์ขึ้นค้นทุกเรือที่เข้าท่า ถ้าพบหนังสือ จะยึดไปคัดลอกที่หอสมุด แล้วคืนให้เจ้าของ แต่บางทีก็คืนฉบับคัดลอก และเก็บฉบับจริงไว้','The king’s officials search every ship that docks. Any book they find is taken to the Library to be copied and returned, though sometimes they return the copy and keep the original.'),
 n:X('หอสมุดอเล็กซานเดรียอาจมีม้วนหนังสือหลายหมื่นถึงหลายแสนม้วน เรื่องการยึดหนังสือจากเรือมาจากแพทย์ชื่อเกเลน ✦ หอสมุดไม่ได้ถูกเผาหมดในวันเดียว แต่เสื่อมไปทีละน้อยตลอดหลายร้อยปี เพราะไฟ สงคราม และการขาดเงิน','The Library of Alexandria may have held tens or even hundreds of thousands of scrolls. The story of seizing books from ships comes from the physician Galen ✦. The Library was not burned in a single day: it declined over centuries through fire, war and lack of money.'),
 o:[opt(X('ช่วยคัดลอกหนังสือ','Help copy the books'),S=>{fx({kn:4,cr:1});S.lit=clamp(S.lit+10,0,100);return X('คุณคัดลอกบทละครที่ไม่มีใครเคยอ่าน และจะไม่มีใครได้อ่านอีกเลยในอีกพันปี','You copy a play no one has read, and that no one will read again in a thousand years.')}),
    opt(X('ซ่อนหนังสือของคุณไว้ใต้ไหปลา','Hide your book under the fish jars'),S=>{fx({b:2});return X('เจ้าหน้าที่ไม่อยากล้วงมือลงไปในไหปลาเค็ม หนังสือของคุณรอด','The officials have no wish to reach into the salt-fish jars. Your book is safe.')})]},
{id:'e16_zeus',deck:'elder',w:12,ch:16,a:[35,90],cond:S=>S.ya<=2235&&S.rg!=='vil',t:X('ซุสหรือจูปิเตอร์','Zeus or Jupiter?'),
 x:X('พ่อค้าชาวโรมันมานั่งดื่มที่ลานตลาด ชี้ไปที่รูปปั้นเทพแล้วพูดว่า “จูปิเตอร์ของเราดีกว่าซุสของพวกเจ้า” คุณตอบว่ามันคือองค์เดียวกัน เขายืนยันว่าไม่ใช่ เพราะชื่อไม่เหมือนกัน ทั้งตลาดเริ่มเลือกข้าง','A Roman trader sits drinking in the market square, points at the statue of the god and says, “Our Jupiter is better than your Zeus.” You reply that they are the same god. He insists not: the names are different. The whole market starts taking sides.'),
 n:X('ทั้งสองคนพูดถูกครึ่งหนึ่ง ชื่อ “ซุส” ในภาษากรีกและ “จูปิเตอร์” ในภาษาละติน มาจากคำเดียวกันในภาษาโบราณที่นักภาษาศาสตร์สร้างขึ้นใหม่ว่า *ดเยอุส แปลว่า “ท้องฟ้า” จูปิเตอร์มาจาก “เทพฟ้า + พ่อ” ชาวกรีกก็เรียกซุสว่า “ซุสผู้เป็นพ่อ” และคัมภีร์พระเวทของอินเดียเรียกเทพแห่งฟ้าว่า “ทยาอุสปิตฤ” ซึ่งก็คือคำเดียวกัน ชาวโรมันรับเรื่องเล่าของเทพกรีกไปมากมาย แต่เทพของโรมเองก็มีพิธีและนิสัยต่างออกไป','Both are half right. Greek “Zeus” and Latin “Jupiter” come from the same ancient word, reconstructed by linguists as *Dyēus, “sky”. Jupiter comes from “sky-god + father”; Greeks too called him “Zeus the father”, and India’s Vedas call the sky god Dyaus Pitar: the very same phrase. The Romans borrowed many Greek stories, but Rome’s own gods kept rites and characters of their own.'),
 o:[opt(X('ตะโกนว่า “ซุสพ่อ”','Shout “Zeus pater!”'),S=>{fx({b:4,so:2});return X('ชาวโรมันตะโกนกลับว่า “จูปิเตอร์!” ทั้งสองฝ่ายโห่กันจนเจ้าของร้านต้องเลี้ยงเหล้าฟรีเพื่อให้เงียบ ตอนจบทุกคนกำลังสาบานด้วยชื่อเดียวกันโดยไม่รู้ตัว','The Roman shouts back, “Iuppiter!” Both sides hoot until the innkeeper pours free wine to quiet them. By the end everyone is swearing by the same name without noticing.')}),
    opt(X('บอกว่าเทพคงไม่สนว่าเราเรียกว่าอะไร','Say the god surely doesn’t care what we call him'),S=>{fx({kn:3,b:3});return X('ชาวโรมันนิ่งไปนาน แล้วยกถ้วยให้คุณ “เพื่อพ่อแห่งท้องฟ้า จะชื่ออะไรก็ตาม”','The Roman is silent a long while, then raises his cup to you: “To the father of the sky, whatever his name.”')})]},
{id:'e16_motto',deck:'elder',w:10,ch:16,a:[50,90],cond:S=>!!S.motto,t:X('คำที่ยึดถือมาทั้งชีวิต','The words of a lifetime'),
 xf:S=>{const m=motto16(S);return X('หลานถามว่าคุณยึดถืออะไรมาทั้งชีวิต คุณนึกถึงคำที่เลือกไว้ตอนหนุ่มสาว: '+m.q.th,'A grandchild asks what you have lived by. You think of the words you chose when young: '+m.q.en)},
 nf:S=>{const m=motto16(S);return X('คำนี้มาจาก'+m.w.th+' คำคมกรีกยังถูกยกมาใช้จนทุกวันนี้ บางประโยคเรารู้ที่มาแน่ชัด บางประโยคเป็นเรื่องเล่าต่อๆ กันมา ✦','These words come from '+m.w.en+'. Greek sayings are still quoted today; some we can trace with certainty, others are stories handed down ✦.')},
 o:[opt(X('บอกว่ายังเชื่ออยู่','Say you still believe it'),S=>{fx({b:5});return X('หลานท่องตาม แล้ววิ่งไปบอกเพื่อน เหมือนที่คุณเคยทำ','The child repeats it and runs to tell friends, as you once did.')}),
    opt(X('บอกว่าชีวิตสอนบางอย่างที่ต่างออกไป','Say life taught you something different'),S=>{fx({kn:3,b:3});return X('หลานถามว่าอะไร คุณใช้เวลาตอบทั้งบ่าย','The child asks what. It takes you all afternoon to answer.')})]}
];
const DEC_CAR16=[
{id:'k16_vase',a:[16,65],w:7,ch:16,cond:S=>S.car==='potter',t:X('เซ็นชื่อบนแจกัน','Signing the vase'),
 x:X('แจกันใบนี้ดีที่สุดที่คุณเคยวาด อะคิลลีสกับอาแจ็กซ์นั่งเล่นหมากรุกกระดานระหว่างสงคราม คุณจะเขียนชื่อตัวเองลงไปไหม','This vase is the best you have ever painted: Achilles and Ajax playing a board game in the middle of the war. Will you write your own name on it?'),
 n:X('ช่างวาดแจกันกรีกบางคนเซ็นชื่อว่า “...วาดฉัน” เอ็กซีเคียสวาดภาพอะคิลลีสกับอาแจ็กซ์เล่นเกมกระดานราว 530 ปีก่อนคริสตกาล บนแจกันที่อยู่ในพิพิธภัณฑ์วาติกันทุกวันนี้ ราว 530 ปีก่อนคริสตกาล ช่างเอเธนส์เริ่มเปลี่ยนจากวาดรูปสีดำบนพื้นแดง เป็นเว้นรูปเป็นสีแดงบนพื้นดำ','Some Greek vase painters signed their work “... painted me”. Exekias painted Achilles and Ajax at a board game around 530 BCE, on a vase now in the Vatican Museums. Around the same time Athenian workshops began switching from black figures on red to red figures on black.'),
 o:[opt(X('เซ็นชื่อ','Sign it'),S=>{fx({cr:3,p:4});addItem('vase16');S.sign16=1;return X('“'+S.name.th+' วาดฉัน” แจกันใบนี้อาจอยู่ได้นานกว่าเมืองของคุณ','“'+S.name.en+' painted me.” This vase may outlast your city.')}),
    opt(X('ไม่เซ็น ให้ภาพพูดแทน','Leave it unsigned: let the picture speak'),S=>{fx({cr:3,b:2});addItem('vase16');return X('สองพันปีต่อมา นักวิชาการจะตั้งชื่อให้คุณจากลายมือ เช่น “จิตรกรแห่งแจกันอะคิลลีส”','Two thousand years later, scholars will name you by your style, something like “the Achilles Painter”.')})]},
{id:'k16_row',a:[16,50],w:6,ch:16,cond:S=>S.car==='rower',t:X('จังหวะเดียวกัน','One stroke'),
 x:X('บนเรือไตรรีม คุณนั่งในความมืดชั้นล่างสุด หัวคุณอยู่ใต้ที่นั่งของคนชั้นบน เหงื่อของเขาหยดใส่คุณ ถ้าใครพายพลาดจังหวะ ไม้พายจะตีกันทั้งแถว','In the trireme you sit in the dark of the lowest bank, your head below the seat of the man above, his sweat dripping on you. If anyone misses the stroke, a whole row of oars clashes.'),
 n:X('ในปี 1987 กองทัพเรือกรีซสร้างเรือไตรรีมจำลองชื่อโอลิมเปียส ฝีพายอาสาสมัครพายได้เร็วราว 9 นอต แสดงว่าฝีพายโบราณต้องฝึกหนักมาก ฝีพายในเอเธนส์ส่วนใหญ่เป็นพลเมืองยากจนและคนต่างถิ่นที่ได้ค่าจ้าง ไม่ใช่ทาสที่ถูกล่ามโซ่อย่างในภาพยนตร์','In 1987 the Greek navy built a reconstructed trireme, the Olympias. Volunteer crews reached about 9 knots, showing how hard ancient rowers must have trained. Most Athenian rowers were poor citizens and paid foreigners, not the chained slaves of the movies.'),
 o:[opt(X('ร้องเพลงให้จังหวะ','Sing to keep the stroke'),S=>{fx({so:3,sv:2});return X('ทั้งชั้นร้องตามคุณ เรือพุ่งไปเร็วจนนายเรือหัวเราะ','The whole bank sings along and the ship leaps forward until the captain laughs.')}),
    opt(X('พายเงียบๆ ประหยัดแรง','Row in silence, saving strength'),S=>{fx({sv:3,h:1});return X('คุณเป็นคนเดียวที่ยังมีแรงเหลือเมื่อถึงท่า','You are the only one with strength left when you reach port.')})]},
{id:'k16_doc',a:[18,70],w:6,ch:16,cond:S=>S.car==='doctor',t:X('เมืองจ้างหมอ','The city physician'),
 x:X('เมืองเล็กแห่งหนึ่งเสนอเงินเดือนให้คุณเป็นหมอประจำเมือง รักษาทุกคนที่ป่วย ทั้งรวยและจน แต่ถ้าใครตาย ญาติจะโทษคุณ','A small town offers you a salary to be its public physician, treating everyone who falls sick, rich or poor. But if anyone dies, the family will blame you.'),
 n:X('นครรัฐกรีกบางแห่งจ้างหมอประจำเมืองด้วยเงินภาษี ตำราของสำนักฮิปพอคราทีสสอนให้จดอาการของคนป่วยทุกวัน และบอกตรงๆ เมื่อรักษาไม่ได้ ตำราเล่มหนึ่งบันทึกกรณีคนไข้ 42 ราย และตายมากกว่าครึ่ง','Some Greek cities paid public physicians from taxes. Hippocratic books taught doctors to record a patient’s symptoms day by day and to say plainly when they could not cure. One book records 42 cases, and more than half the patients died.'),
 o:[opt(X('รับงาน','Accept'),S=>{S.ag+=3;fx({p:5,so:2});return X('คุณได้เห็นโรคทุกชนิดที่มีในโลก และจดทุกอย่างไว้','You see every illness there is, and write everything down.')}),
    opt(X('รักษาเฉพาะคนรวยดีกว่า','Better to treat only the rich'),S=>{S.ag+=4;fx({b:-2});return X('รวยขึ้นเร็ว แต่คุณไม่ได้เห็นโรคใหม่ๆ เลย','You grow rich fast, but you never see anything new.')})]},
{id:'k16_think',a:[20,75],w:6,ch:16,cond:S=>S.car==='thinker',t:X('สอนเพื่อเงิน','Teaching for pay'),
 x:X('พ่อรวยคนหนึ่งเสนอเงินก้อนใหญ่ให้คุณสอนลูกชายพูดในสภาให้ชนะทุกครั้ง ไม่ว่าเรื่องนั้นจะถูกหรือผิด','A rich father offers you a large sum to teach his son to win every debate in the assembly, whether he is right or wrong.'),
 n:X('นักสอนการพูดที่เดินทางรับเงินสอนเรียกว่า “โซฟิสต์” คำนี้เดิมแปลว่าผู้มีปัญญา แต่เพลโตและโสกราตีสดูถูกพวกเขาว่าขายการพูดเก่งแทนความจริง จนคำว่า sophistry ในภาษาอังกฤษแปลว่าการเล่นลิ้นหลอกลวง','Travelling teachers of speaking who charged fees were called sophists. The word once meant “wise ones”, but Plato and Socrates scorned them for selling cleverness instead of truth, so that English sophistry now means deceptive argument.'),
 o:[opt(X('รับเงิน','Take the money'),S=>{S.ag+=5;fx({so:2,b:-1});return X('ลูกศิษย์ชนะการเถียงครั้งแรกด้วยเหตุผลที่คุณเองก็ไม่เชื่อ','Your pupil wins his first debate with an argument you do not believe yourself.')}),
    opt(X('บอกว่าสอนได้แค่การถามหาความจริง','Say you can only teach how to seek the truth'),S=>{fx({kn:3,p:2});return X('พ่อรวยเดินจากไปแบบหงุดหงิด แต่ลูกชายแอบกลับมาฟังคุณทุกวัน','The rich father stalks off, but the son slips back to listen to you every day.')})]},
{id:'k16_hop',a:[18,50],w:5,ch:16,cond:S=>S.car==='hoplite',t:X('แถวโล่','The shield wall'),
 x:X('กองทัพสองเมืองเผชิญหน้ากันบนที่ราบ ทั้งสองฝ่ายเป็นชาวนาที่ต้องรีบกลับไปเก็บเกี่ยว ในแถวโล่ ทุกคนเบียดไปทางขวาเพื่อหลบหลังโล่ของคนข้างๆ','Two cities’ armies face each other on a plain, both full of farmers who need to get back for the harvest. In the shield wall everyone edges to the right, to hide behind the next man’s shield.'),
 n:X('การรบของโฮพลไลต์มักจบในวันเดียว แถวหน้าดันกันด้วยโล่จนฝ่ายหนึ่งแตกหนี ธิวซิดิดีสสังเกตว่ากองทัพมักเบี้ยวไปทางขวา เพราะทุกคนพยายามหลบหลังโล่ของคนทางขวา','Hoplite battles usually ended in a single day: the front ranks shoved with their shields until one side broke. Thucydides noticed that armies drifted to the right, as each man tried to shelter behind the shield of the man on his right.'),
 o:[opt(X('ยืนให้มั่นในแถว','Hold your place in the line'),S=>{if(rnd()<.15){fx({h:-14});S.inj=1;return X('หอกแทงผ่านช่องระหว่างโล่ถูกไหล่คุณ แต่แถวไม่แตก','A spear finds the gap between shields and pierces your shoulder, but the line holds.')}fx({sv:3,p:4});return X('ฝ่ายตรงข้ามแตกก่อน ทุกคนกลับบ้านทันเก็บเกี่ยว','The other side breaks first. Everyone gets home for the harvest.')}),
    opt(X('ปกป้องคนทางซ้าย','Cover the man on your left'),S=>{fx({so:4,p:2,h:-3});return X('แขนคุณเจ็บไปทั้งเดือน แต่เพื่อนทางซ้ายรอดมาได้','Your arm aches for a month, but the man on your left lives.')})]}
];
